// كتاب الصلاة — القسم الأول (ب): ما قُرئ فعلًا من الصور (ص129–193)
const { NO_N, NO_O } = require('../b4/common');

module.exports = [
  {
    title: `باب التشهد في الصلاة — تتمة (ص129–131)`,
    items: [
      { q: `«ربنا لك الحمد» و«ربنا ولك الحمد»: إثبات الواو وحذفها، وعطف «ربنا» على ما قبلها`, p: `129`,
        n: `قوله: (ربنا لك الحمد) هكذا هو هنا بلا واو وفي غير هذا الموضع (ربنا ولك الحمد) وقد جاءت الأحاديث الصحيحة بإثبات الواو وبحذفها وكلاهما جاءت به روايات كثيرة والمختار أنه على وجه الجواز وأن الأمرين جائزان ولا ترجيح لأحدهما على الآخر، ونقل القاضي عياض اختلافًا عن مالك رحمه الله تعالى وغيره في الأرجح منهما وعلى إثبات الواو يكون قوله [ربنا] متعلقًا بما قبله تقديره سمع الله لمن حمده يا ربنا فاستجب حمدنا ودعاءنا ولك الحمد على هدايتنا لذلك.`,
        o: `مالك وغيره: اختلاف في الأرجح (إثبات الواو أو حذفها). المختار عند النووي: جائزان ولا ترجيح.`,
        s: `ونحن نرجح إضافة الواو فيقول (اللَّهُمَّ رَبَّنَا ولَكَ الْحَمْدُ) ففيه إثبات الربوبية وجملة أخرى وهي الحمد فهي أكمل معنى والله أعلم. وإن فعل أي الأمرين أو فعله لبيان الجواز أجزئ.`,
        f: [] },
      { q: `الاستدلال بقوله «وإذا كان عند القعدة فليكن من أول قول أحدكم التحيات» على أن لا تُقال البسملة في أول التشهد`, p: `129`,
        n: `قوله: (وإذا كان عند القعدة فليكن من أول قول أحدكم التحيات) استدل جماعة بهذا على أنه يقول في أول جلوسه التحيات ولا يقول بسم الله وليس هذا الاستدلال بواضح لأنه قال فليكن من أول ولم يقل فليكن أول والله أعلم.`,
        o: NO_O,
        s: `الصحيح أن هذا الاستدلال صحيح من جهة أن (بسم الله) لم ترد، فطالما أنها لم ترد في شيء من الروايات فلا يقول (بسم الله) في التحيات، وإنما يبدأ بلفظ التحيات.`,
        f: [] },
      { q: `قول مسلم «ليس كل شيء عندي صحيح وضعته ها هنا إنما وضعت ها هنا ما أجمعوا عليه» (معنى الإجماع عنده وشرطه)`, p: `130`,
        n: `قوله: (وفي حديث جرير عن سليمان التيمي عن قتادة من الزيادة وإذا قرأ فأنصتوا) هكذا (قال أبو إسحاق: قال أبو بكر بن أخت أبي النضر في هذا الحديث. فقال مسلم: تريد أحفظ من سليمان فقال له أبو بكر فحديث أبي هريرة فقال هو صحيح يعني وإذا قرأ فأنصتوا. فقال لم لم تضعه ها هنا؟ قال: ليس كل شيء عندي صحيح وضعته ها هنا إنما وضعت ها هنا ما أجمعوا عليه.)`,
        o: NO_O,
        s: `يريد مسلم أن يقول أن هذه الزيادة (وإذا قرأ فأنصتوا) ثابتة، وحديث (وإذا قرأ فأنصتوا) حديث أبي موسى الأشعري... فحديث أبو هريرة لم يخرجه مسلم في صحيحه ولكن أخرج رواية أبي موسى، ولكنه صحح رواية أبي هريرة. [قال: ليس كل شيء عندي صحيح وضعته ها هنا إنما وضعت ها هنا ما أجمعوا عليه]: فهذا كلام مسلم رحمه الله الذي جعل كتابه بهذه المنزلة، وهو أنه ليس كل شيء صححه فهو موجود في الصحيح، فهذا دليل على أنه لم يستوعب ولم يرد استيعاب الصحيح، وهذا رد على من يقول: أننا نعمل بما في الصحيحين فقط ولا نبحث عن غيرهما؛ فإن الإمام البخاري قد صحح أحاديث كثيرة نقلها الترمذي عنه وصحح هو أحاديث في جزء القراءة وفي غيره من كتبه، فصحح أحاديث لم يُخرجها في الصحيح، فدل ذلك على أنه لم يرد هو ولا مسلم أن يستوعبا الصحيح، بمعنى أنهم لم يقولوا أن الأحاديث الصحيحة هي التي في الكتابين فقط، بل فيها وفي غير هذين الكتابين ولكنهم وضعوا فيها أعلى درجات الصحة. ولكن كيف يجمع بين هذا وبين أن هناك أحاديث في مسلم لم يجمع عليها وقد استدركت عليه، ولكن معظم الأحاديث مجمعٌ عليها متلقاه بالقبول؟ والجواب: أن مذهب مسلم أن ما اجمعوا عليه يرى أنه لا ينبغي أن يختلف فيه، وبالتأكيد أنه اطلع على الخلاف في بعض الرواة وفي بعض الأحاديث ولكنه رأى أنه خلاف لا ينبغي أن يختلف. والله أعلم، وما لم يستدرك عليه هو فعلًا محل إجماع، هو البخاري. ولذلك نقول الذي يطعن في أحاديث البخاري ومسلم غير التي استدركت عليها مخالف للإجماع ومبتدع ضال، وذلك لأن مسلم نقل في صحيحه ما أجمعوا عليه، وسوف نستثني من عبارة مسلم فقط المستدركات التي استدركت على البخاري ومسلم، وفضلًا أن الأمة كلها تلقت أحاديثهما بالقبول، فهذا إجماع من يخالفه مطعون فيه.`,
        f: [] },
      { q: `زيادة «وإذا قرأ فأنصتوا» في حديث التشهد: هل هي شاذة؟ وما معنى المخالفة والشذوذ عند المحدثين؟`, p: `131–132`,
        n: `واعلم أن هذه الزيادة وهي قوله: (وإذا قرأ فأنصتوا) مما اختلف الحافظ في صحته فروى البيهقي في السنن الكبير عن أبي داود السجستاني أن هذه اللفظة ليست بمحفوظة وكذلك رواه عن يحيى بن معين وأبي حاتم الرازي والدارقطني والحافظ أبي علي النيسابوري شيخ الحاكم قال البيهقي: [ قال أبو علي: الحافظ هذه اللفظة غير محفوظة قد خالف سليمان التيمي فيها جميع أصحاب قتادة واجتماع هؤلاء الحفاظ على تضعيفها مقدم على تصحيح مسلم لا سيما ولم يروها مسندة في صحيحه والله أعلم ].`,
        o: `أبو داود وابن معين وأبو حاتم والدارقطني وأبو علي النيسابوري: اللفظة غير محفوظة (مخالفة سليمان التيمي لجميع أصحاب قتادة). مسلم: صحيحة (صححها).`,
        s: `هذا الكلام فيه نظر، فإن من ضعفها قال لم يروها غير سليمان حتى ولو كان ذلك لا يستوجب التضعيف، وهذه اللفظة أولًا مروية من أكثر من وجه من حديث أبي هريرة ومن حديث أبي موسى فهذا شاهد له على الصحة، ثم ليس الشذوذ أن يروي الراوي ما لم يروِ غيره، وإنما أن يروي مخالفًا غيره وهذا هو الصحيح، وكثير من المتقدمين يجعل عدم رواية الحفاظ للفظة قادحًا في رواية أحدهم لها، والصحيح الذي عليه عامة علماء الحديث أن الشذوذ هو رواية الثقة مخالفًا لما رواه غيره وليس أنه يروي مالم يروِ غيره، والمخالفة تكون فهم لم يقولوا (وَإِذَا قَرَأَ فَأَنْصِتُوا) ولم يقولوا: وإذا قرأ فاقرأوا، فتكون المخالفة إذا قالوا: وإذا قرأ فاقرأوا، ولكن إذا سكتوا تمامًا عنها فليس هذا بشذوذ، بمعنى أن لو أن الحفاظ قالوا أن الراوي قال [تسعة] وواحد قال [ثمانية] فهذا قادح وهذا يكون الشذوذ، ولكنهم لو لم يذكروا عدد وقالوا أن واحدًا قال [تسعة] أو [ثمانية] فهذا لا يكون قادحًا والله أعلم. وكما قلنا أنها ليست علة وهي زيادة ثقة وزيادة الثقة مقبولة. وهذا موضع لا ينبغي أن يختلف فيه، وللعلم فإن عامة الأحاديث التي أخذت على البخاري ومسلم ليست على متونها وإنما على أسانيدها، والتي في متونها كلام يسيرٌ لا تتجاوز أصابع اليد الواحدة أو الاثنين على الأكثر في مسلم، فالذي استدركه الدارقطني مثلًا معظمه في الأسانيد مع إثبات صحة الحديث.`,
        f: [`(ص131) «فضلًا أنه غير مخالف بل روى ما لم يرِ غيره فهي زيادة ثقة وزيادة الثقة مقبولة.»`, `(ص131) «فكما قلنا ينبغي أن تكون محل إجماع.»`] },
    ],
  },
  {
    title: `باب الصلاة على النبي ﷺ بعد التشهد (ص132–136)`,
    items: [
      { q: `حكم الصلاة على النبي ﷺ بعد التشهد الأخير: سنة أم واجبة أم ركن؟`, p: `134`,
        n: `اعلم أن العلماء اختلفوا في وجوب الصلاة على النبي ﷺ عقب التشهد الأخير في الصلاة: فذهب أبو حنيفة ومالك رحمهما الله تعالى والجماهير إلى أنها سنةٌ لو تركت صحت الصلاة. وذهب الشافعي وأحمد رحمهما الله تعالى إلى أنها واجبةٌ، لو تركت لم تصح الصلاة وهو مروي عن عمر بن الخطاب وابنه عبد الله رضي الله عنهما وهو قول الشعبي. وقد نسب جماعة الشافعي رحمه الله تعالى في هذا إلى مخالفة الإجماع ولا يصح قولهم فإنه مذهب الشعبي كما ذكرنا وقد رواه عن البيهقي. وفي الاستدلال لوجوبها خفاء وأصحابنا يحتجون بحديث أبي مسعود الأنصاري ﵁ المذكور هنا أنهم قالوا كيف نصلي عليك يا رسول الله فقال: (قولوا اللهم صلي على محمد.. إلى آخره)، قالوا: والأمر للوجوب وهذا القدر لا يظهر الاستدلال به إلا إذا ضمّ إليه الرواية الأخرى: (كيف نصلي عليك إذا نحن صلينا عليك في صلاتنا)، فقال ﷺ: قولوا اللهم صل على محمد وعلى آل محمد.. إلى آخره) وهذه الزيادة صحيحةٌ رواها الإمامان الحافظان أبو حاتم بن حبان وأبو عبد الله الحاكم في صحيحيهما قال الحاكم هي زيادة صحيحة، واحتج لها أبو حاتم وأبو عبد الله أيضًا في صحيحيهما بها رويا: عن فضالة بن عبيد ﵁ أن رسول الله ﷺ رأى رجلًا يصلي لم يحمد الله ولم يمجده ولم يصل على النبي ﷺ فقال النبي ﷺ: [عجّل هذا] ثم دعاه النبي ﷺ فقال: [إذا صلى أحدكم فليبدأ بحمد ربه والثناء عليه وليصل على النبي ﷺ وليدع ما شاء]. قال الحاكم هذا حديث صحيح على شرط مسلم وهذان الحديثان وإن اشتملا على ما لا يجب بالإجماع كالصلاة على الآل والذرية والدعاء فلا يمتنع الاحتجاج بها فإن الأمر للوجوب فإذا خرج بعض ما يتناوله الأمر عن الوجوب بدليل بقي الباقي على الوجوب. والله أعلم. والواجب عند أصحابنا: [اللهم صل على محمد] وما زاد عليه سنة. ولنا وجه شاذ أنه يجب الصلاة على الآل وليس بشيء والله أعلم.`,
        o: `أبو حنيفة ومالك والجماهير: سنة لو تركت صحت الصلاة. الشافعي وأحمد: واجبة لا تصح الصلاة بتركها (ومروي عن عمر وابنه والشعبي). وجه شاذ عند الشافعية: يجب الصلاة على الآل. (طاووس والشوكاني وكثير من أئمة أهل البيت يرون وجوب الصلاة على الآل).`,
        s: `ولكن مذهب أحمد أنها واجبة وليست ركنًا لو نسيها سجد للسهو وصحت صلاته ولو جهلها أو جهل وجوبها صحت صلاته، ولكن لو تركها عمدًا مع العلم والقدرة بطلت صلاته، والشافعي يرى أنها واجبة مطلقًا فالواجب عند الشافعي هو الركن. أي الاستفادة في وجوبها في الصلاة من هذه الرواية، ويمكن أن يستدل بها على ما هي عليه، ف[أَمَرَنَا اللَّهُ تَعَالَى أَنْ نُصَلِّيَ عَلَيْكَ يَا رَسُولَ اللَّهِ فَكَيْفَ نُصَلِّي عَلَيْكَ؟] أي أمرنا عند ذكرك، كل ما ذكر، فلو كان واجبًا كلها ذُكر فدخل في ذلك وجوبه في الصلاة، وهذا قول متجه رغم أنه خلاف عامة العلماء وهو أنه يجب الصلاة على النبي ﷺ كلما ذُكر كما في قوله ﷺ: (رَغِمَ أَنْفُ رَجُلٍ ذُكِرْتُ عِنْدَهُ فَلَمْ يُصَلِّ عَلَيَّ) حديث صحيح، و(رَغِمَ) أي ذل، ولا عقوبة إلا لترك واجب. (حديث صحيح) وهذا دليل صحيح، وهذا حديث صحيح ويدل على مذهب أحمد تمامًا، وهو أنه إذا تركها جاهلًا بوجوبها لم تبطل صلاته لأنه لم يأمره بالإعادة، وهو دليل أيضًا على أن التشهد من الواجبات وليس من الأركان لأن الحمد والثناء هنا إنما هو التشهد لقوله (التحيات لله). فيجعل الصارف للأمر على آل النبي ﷺ الإجماع مع أن هذا الإجماع فيه نظر. ولا ندري ما الصارف إذا لم يثبت الإجماع، أين الإجماع على عدم وجوب الصلاة على الآل؟ ولكنه قولٌ نادر، وأما عدم وجوب الدعاء فقد قال طاووس بوجوب الاستعاذة من الأربع وهو قول قوي لظاهر الحديث، فأقل شيء أن يقول (اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ) فهذا أحوط، وإن قال (اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ) أجزئ عند جمهور أهل العلم، والشوكاني يرجح وجوب الصلاة على الآل، ومذهب كثير من أئمة أهل البيت وجوب الصلاة على الآل، فلا ندري ما وجه هذا النقل للإجماع مع العلم بوجود المخالف.`,
        f: [`(ص134) ولكن مذهب أحمد أنها واجبة وليست ركنًا لو نسيها سجد للسهو وصحت صلاته ولو جهلها أو جهل وجوبها صحت صلاته، ولكن لو تركها عمدًا مع العلم والقدرة بطلت صلاته، والشافعي يرى أنها واجبة مطلقًا فالواجب عند الشافعي هو الركن.`] },
      { q: `المراد بـ«آل النبي ﷺ» في الصلاة عليه: مذاهب العلماء`, p: `135–136`,
        n: `واختلف العلماء في آل النبي ﷺ على أقوال: أظهرها وهو اختيار الأزهري وغيره من المحققين أنهم جميع الأمة. والثاني بنو هاشم وبنو المطلب. والثالث أهل بيته ﷺ وذريته والله أعلم.`,
        o: `الأظهر عند النووي والأزهري: جميع الأمة. الثاني: بنو هاشم وبنو المطلب. الثالث: أهل بيته وذريته.`,
        s: `القول الثاني هو الأظهر عندي، وهو من حُرمت عليهم الصدقة [بنو هاشم وبنو المطلب] وأزواجه ﷺ من أهل بيته بدليل الحديث: (اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى أَزْوَاجِهِ وَذُرِّيَّتِهِ) ولا شك في أن ذرِّيته من أهل البيت لأنهم من نسل فاطمة وعلي ابن أبي طالب فلا ذرية للنبي ﷺ إلا من هؤلاء وهم من بني هاشم، وأزواجه من أهل بيته.` },
      { q: `سؤال من لا يفهم مراد الأمر: هل كان سؤال الصحابة عن الصلاة في الصلاة أم في غيرها؟ ولماذا ذُكر الحديث في كتاب الصلاة؟`, p: `136`,
        n: `قوله (أمرنا الله تعالى أن نصلي عليك يا رسول الله فكيف نصلي عليك) معناه أمرنا الله تعالى بقوله تعالى: (صلوا عليه وسلموا تسليمًا) فكيف نلفظ بالصلاة؟ وفي هذا أن من أمر بشيء لا يُفهم مراده يُسأل عنه ليعلم ما يأتي به. قال القاضي: [ويحتمل أن يكون سؤالهم عن كيفية الصلاة في غير الصلاة ويحتمل أن يكون في الصلاة. قال: وهو الأظهر. قلتُ: وهذا ظاهر اختيار مسلم ولهذا ذكر هذا الحديث في هذا الموضع].`,
        o: NO_O,
        s: `أي بعد وجوب التشهد فقد أتى بوجوب الصلاة على النبي ﷺ، فلو كان عنده مطلقًا لوضعه في [الأذكار] ولكنه وضعه في [كتاب الصلاة].`,
        f: [] },
      { q: `الحكمة في تشبيه الصلاة على محمد ﷺ بالصلاة على إبراهيم مع أنه أفضل منه (الأقوال الثلاثة)`, p: `137–138`,
        n: `واختلف العلماء في الحكمة في قوله: [اللهم صل على محمد كما صليت على إبراهيم] مع أن محمدًا ﷺ أفضل من إبراهيم ﷺ: قال القاضي عياض: أظهر الأقوال أن نبينا ﷺ سأل ذلك لنفسه ولأهل بيته ليتم النعمة عليهم كما أتمها على إبراهيم وعلى آله. وقيل بل سأل ذلك لأمته. وقيل بل ليبقى ذلك له دائمًا إلى يوم القيامة ويجعل له به لسان صدق في الآخرين كإبراهيم ﷺ. وقيل كان ذلك قبل أن يعلم أنه أفضل من إبراهيم ﷺ. وقيل سأل صلاة يتخذه بها خليلًا كما اتخذ إبراهيم. هذا كلام القاضي. والمختار في ذلك أحد ثلاثة أقوال: أحدها حكاه بعض أصحابنا عن الشافعي رحمه الله تعالى أن معناه: صل على محمد وتم الكلام هنا ثم استأنف وعلى آل محمد أي وصل على آل محمد كما صليت على إبراهيم وآل إبراهيم، فالمسئول له مثل إبراهيم وآله هم آل محمد ﷺ لا نفسه. القول الثاني معناه: اجعل لمحمد وآله صلاة منك كما جعلتها لإبراهيم وآله، فالمسئول المشاركة في أصل الصلاة لا قدرها. القول الثالث أنه على ظاهره والمراد: اجعل لمحمد وآله صلاة بمقدار الصلاة التي لإبراهيم وآله، والمسئول مقابلة الجملة. فإن المختار في الآل كما قدمناه أنهم جميع الأتباع ويدخل في آل إبراهيم خلائق لا يحصون من الأنبياء ولا يدخل في آل محمد ﷺ نبي فطلب إلحاق هذه الجملة التي فيها نبي واحد بتلك الجملة التي فيها خلائق من الأنبياء. والله أعلم.`,
        o: `القاضي عياض وغيره: سأله لنفسه ولأهل بيته ليتم النعمة؛ أو لأمته؛ أو ليبقى له لسان صدق؛ أو قبل أن يعلم أنه أفضل؛ أو سأل صلاة يتخذه بها خليلًا. والمختار عند النووي أحد ثلاثة أقوال (الأول: حكاه بعض الشافعية عن الشافعي: «وعلى آل محمد» استئناف؛ الثاني: المشاركة في أصل الصلاة لا قدرها؛ الثالث: بمقدار صلاة إبراهيم وآله مقابلة الجملة بالجملة).`,
        s: `والقول الثالث هو أقرب الأقوال عندي. بمعنى أن آل إبراهيم فيه كل الأنبياء فهو يطلب صلاة عليه مجموع ما على إبراهيم وعلى الأنبياء وخصوصًا وأن كل الأنبياء من بعده من ذريته، فكل الأنبياء والصالحين من ذرية إبراهيم مطلوبٌ للنبي ﷺ صلاةٌ بمجموع كل هذه الصلوات.`,
        f: [] },
      { q: `الدعاء للنبي ﷺ بالرحمة في الصلاة عليه (اللهم ارحم محمدًا) والتقصير في ذكر الرحمة`, p: `138–139`,
        n: `قال القاضي عياض: ولم يجئ في هذه الأحاديث ذكر الرحمة على النبي ﷺ وقد وقع في بعض الأحاديث الغريبة. قال: واختلف شيوخنا في جواز الدعاء للنبي ﷺ بالرحمة: فذهب بعضهم وهو اختيار أبي عمر بن عبد البر إلى أنه لا يقال، وأجازه غيره وهو مذهب أبي محمد بن أبي زيد، وحجة الأكثرين تعليم النبي ﷺ الصلاة عليه وليس فيها ذكر الرحمة، والمختار أنه لا يذكر الرحمة.`,
        o: `ابن عبد البر والأكثرون: لا يقال (اللهم ارحم محمدًا). ابن أبي زيد القيرواني وغيره: يجوز.`,
        s: `أي لا يذكر الرحمة في الصلاة على النبي ﷺ، وأما أن النبي ﷺ يصح له الدعاء بالرحمة فنعم، ولكن لا على سبيل الشعار، فلا تقول [محمد رحمه الله] ولكن نقول (محمد ﷺ)، الشعار الصلاة والسلام على النبي ﷺ لأنه شعار لازم فكلما يُذكر يُصلى ويسلم عليه ﷺ وإلا فقد قال النبي ﷺ في التشهد (السلام عليك أيها النبي ورحمة الله وبركاته) وهو دعاء بالرحمة، ولكن لا على سبيل الشعار، كما لا يصح على سبيل الشعار القول [محمد عز وجل] ولا [محمد رضي الله عنه] وهو قد رضي الله عنه، وكذلك ولا الصحابة [صلى الله عليهم وسلم] فكلٌ يختص بها جرت عليه عادة أهل السنة. (وقد أتت الرحمة مع السلام ولم تأتِ الرحمة مع الصلاة.)`,
        f: [`(ص139) والأول هو المشهور وهو البركة الخير الكثير المتزايد، ولا مانع من اجتماع ذلك، لأن الثبات مع الزيادة لا يتنافى فقد ثبت على الأول وزاد عليه. (تعليقًا على معنى «وبارك»: الزيادة في الخير والكرامة أو الثبات.)`] },
      { q: `الصلاة على غير الأنبياء استقلالًا: (اللهم صل على أبي بكر) وحكمها (مكروهة أم خلاف الأولى؟)`, p: `139–141`,
        n: `وقوله: (اللهم صل على محمد وعلى آل محمد) احتج به من أجاز الصلاة على غير الأنبياء وهذا مما اختلف العلماء فيه: فقال مالك والشافعي رحمهما الله تعالى والأكثرون: لا يُصلى على غير الأنبياء استقلالًا فلا يقال اللهم صل على أبي بكر أو عمر أو علي أو غيرهم ولكن يصلى عليهم تبعًا فيقال اللهم صل على محمد وآل محمد وأصحابه وأزواجه وذريته كما جاءت به الأحاديث. وقال أحمد وجماعة: يصلى على كل واحد من المؤمنين مستقلًّا، واحتجوا بأحاديث الباب وبقوله ﷺ: (اللهم صل على آل أبي أوفى)، وكان إذا أتاه قوم بصدقتهم صلى عليهم، قالوا وهو موافق لقول الله تعالى: (هو الذي يصلي عليكم وملائكته). واحتج الأكثرون بأن هذا النوع مأخوذ من التوقيف واستعمال السلف ولم يُنقل استعمالهم ذلك بل خصوا به الأنبياء كما خصوا الله تعالى بالتقديس والتسبيح فيقال قال الله سبحانه وتعالى وقال الله تعالى وقال ﷻ وقال جلت عظمته وتقدست أسماؤه وتبارك وتعالى ونحو ذلك ولا يقال قال النبي ﷺ وإن كان عزيزًا جليلًا ولا نحو ذلك؛ وأجابوا عن قول الله تعالى (هو الذي يصلي عليكم وملائكته) وعن الأحاديث: بأن ما كان من الله ﷻ ورسوله فهو دعاءٌ وترحمٌ وليس فيه معنى التعظيم والتوقير الذي يكون من غيرهما وأما الصلاة على الآل والأزواج والذرية فإنها جاء على التبع لا على الاستقلال وقد بينّا أنه يقال تبعًا لأن التابع يُحتمل فيه ما لا يُحتمل استقلالًا. واختلف أصحابنا في الصلاة على غير الأنبياء هل يقال هو مكروه أو هو مجرد ترك أدب، والصحيح المشهور أنه مكروه كراهة تنزيه. قال الشيخ أبو محمد الجويني: [والسلام في معنى الصلاة]، فإن الله تعالى قرن بينهما فلا يُفرد به غائب غير الأنبياء فلا يقال أبو بكر وعمر وعلي عليهم السلام وإنما يقال ذلك خطابًا للأحياء والأموات فيقال السلام عليكم ورحمة الله والله أعلم.`,
        o: `مالك والشافعي والأكثرون: لا يُصلى على غير الأنبياء استقلالًا، ويُصلى عليهم تبعًا. أحمد وجماعة: يصلى على كل مؤمن مستقلًّا. وعند الشافعية: مكروهة كراهة تنزيه (الصحيح المشهور)، أو ترك أدب. والسلام في معنى الصلاة.`,
        s: `هذا الكلام في النقل نعم إذا كان في الشعار كما ذكرنا، أما أنه لم يُنقل آحاد في بعض المواطن دون أن يكون شعارًا فمن أين ذلك؟ فالأحاديث ثابتة وأقوال العلماء منهم الإمام أحمد وغيره ومن وافقه ثابتة في ذلك، فكلامه أنه لم ينقل عن السلف فهل هو مطلقًا أم على سبيل الشعار؟ فهو لم يُنقل على سبيل الشعار. (دون أن يُجعل شعارًا كما ذكرنا.) وهذا معنى صحيح، فلو أخذ الذي يجمع الصدقة الزكاة من قوم فقال اللهم صل عليهم صح ذلك، وهذا هو الصحيح. ووجه الاستدلال من الآية أن الملائكة تصلي على المؤمنين. (فلو قيل «اللهم صل على أبي بكر» فهل يكره أم ترك الأدب؟ أي ترك الأدب أي ترك الأولى وهو أقل من مرتبة الكراهة.) عامة أهل السنة على ذلك أيضًا في باب الشعار إلا أن طائفة كبيرة من المتقدمين من أهل السنة وهي مليئة في البخاري وهي السلام على أهل البيت فالبخاري مليء بفاطمة عليها السلام وعلي عليه السلام والحسن والحسين عليهما السلام، وبالطبع فاطمة أكثر فمرات عديدة في البخاري وغيره من كتب الحديث فيها ذكر السلام على أهل البيت، ولكن الأولى في هذا المقام أن يصلى ويسلم على الأنبياء، وإن كان كثير من المتأخرين يسلم على الأنبياء غير النبي ﷺ حتى ظن بعض الناس أن الصلاة مختصة بالنبي ﷺ وليس كذلك، بل يُقال لجميع الأنبياء [ﷺ] ويُرضى عن الصحابة ويترحم على من دونهم، وإن خالف في ذلك لم يحرم ولم يُكره وإنها خالف الأولى، فمثلًا لو قال: الإمام النووي ﷺ فالأحسن أن يُقال [رحمه الله].`,
        f: [`(ص140) (دون أن يُجعل شعارًا كما ذكرنا.) وهذا معنى صحيح، فلو أخذ الذي يجمع الصدقة الزكاة من قوم فقال اللهم صل عليهم صح ذلك، وهذا هو الصحيح. ووجه الاستدلال من الآية أن الملائكة تصلي على المؤمنين.`] },
      { q: `معنى «من صلى عليَّ واحدة صلى الله عليه عشرًا» والجمع مع «وإن ذكرني في ملأ ذكرته في ملأ خير منهم»`, p: `141`,
        n: `قوله ﷺ: (من صلى عليَّ واحدة صلى الله عليه عشرًا) قال القاضي: معناه رحمته وتضعيف أجره كقوله تعالى: (من جاء بالحسنة فله عشر أمثالها) قال: وقد يكون الصلاة على وجهها وظاهرها تشريفًا له بين الملائكة، كما في الحديث: (وإن ذكرني في ملأ ذكرته في ملأ خير منهم).`,
        o: `القاضي عياض: معناه رحمته وتضعيف أجره، وقد تكون الصلاة على ظاهرها تشريفًا بين الملائكة.`,
        s: `وهذا هو الصحيح، فليس هناك معارضة، فالرحمة والثناء فيثني عليه ﷺ عشرًا عند الملائكة في الملأ الأعلى كما في الحديث: (فإن ذكرني في ملأ ذكرته في ملأ خيراً منه).`,
        f: [] },
    ],
  },
  {
    title: `باب التسميع والتحميد والتأمين (ص142–145)`,
    items: [
      { q: `التأمين: متى يكون من المأموم؟ والجهر به للإمام والمنفرد والمأموم، وتأمين الإمام في الجهرية`, p: `143–144`,
        n: `في هذه الأحاديث: استحباب التأمين عقب الفاتحة للإمام والمأموم والمنفرد، وأنه ينبغي أن يكون تأمين المأموم مع تأمين الإمام لا قبله ولا بعده لقوله ﷺ: [وإذا قال ولا الضالين فقولوا آمين]، وأما رواية: [إذا أمّن فأمّنوا] فمعناها إذا أراد التأمين. وقد قدمنا بيان هذا قريبًا في حديث أبي موسى في باب التشهد. ويسن للإمام والمنفرد الجهر بالتأمين وكذا للمأموم على المذهب الصحيح هذا تفصيل مذهبنا. وقد اجتمعت الأمة على أن المنفرد يؤمّن وكذلك الإمام والمأموم في الصلاة السرية: وكذلك قال الجمهور في الجهرية. وقال مالك رحمه الله تعالى في رواية: لا يؤمّن الإمام في الجهرية. وقال أبو حنيفة ﵁ والكوفيون ومالك في رواية لا يجهر بالتأمين. وقال الأكثرون يجهر.`,
        o: `مالك (رواية): لا يؤمن الإمام في الجهرية. أبو حنيفة والكوفيون ومالك (رواية): لا يجهر بالتأمين. الأكثرون: يجهر.`,
        s: `وهذه يُحتج بمثلها في التحميد أيضًا لأن نفس اللفظ الذي ورد في التحميد هو الذي ورد في التأمين حيث قال: (فَإِنَّهُ مَنْ وَافَقَ تَأْمِينُهُ تَأْمِينَ الْمَلاَئِكَةِ غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ) وفي التحميد قال: (فَإِنَّهُ مَنْ وَافَقَ قَوْلُهُ قَوْلَ الْمَلاَئِكَةِ غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ) فينبغي أن يكون تحميده مع تحميد الملائكة فيقتضي هذا أن يكون تحميده وتحميد الإمام واحدًا كما كان تأمينه وتأمين الإمام واحدًا ليوافق تأمين الملائكة وتحميدهم. (أو نقول [فأمنوا مع تأمينه] بدلالة حديث: [ وإذا قال وَلاَ الضَّالِّينَ فَقُولُوا آمِينَ].) وهذا خلاف ظاهر الحديث (إذا أمّن فأمّنوا) إذا الإمام يؤمن من يقول آمين. وذلك للإمام والمأموم والمنفرد للحديث وهو في السنن الكبرى للبيهقي: [عَنْ عَطَاءٍ قَالَ: "أَدْرَكْتُ مِائَتَيْنِ مِنْ أَصْحَابِ النَّبِيِّ ﷺ فِي هَذَا الْمَسْجِدِ إِذَا قَالَ الإِمَامُ: {غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلاَ الضَّالِّينَ} [الفاتحة: ٧]، سَمِعْتُ لَهُمْ رَجَّةً بِآمِينَ" وَرَوَاهُ إِسْحَاقُ الْحَنْظَلِيُّ، عَنْ عَلِيِّ بْنِ الْحَسَنِ، وَقَالَ: (رَفَعُوا أَصْوَاتَهُمْ بِآمِينَ). ] وهذا يقتضي أنهم يجهرون جميعًا في صوت واحد.` },
      { q: `معنى «من وافق قوله قول الملائكة»: الموافقة في الوقت أم في الصفة والخشوع؟ ومن هم الملائكة المقصودون؟`, p: `144–145`,
        n: `وقوله ﷺ: [من وافق قوله قول الملائكة]، [ومن وافق تأمينه تأمين الملائكة]: معناه وافقهم في وقت التأمين فأمّن مع تأمينهم فهذا هو الصحيح والصواب. وحكى القاضي عياض قولًا أن معناه وافقهم في الصفة والخشوع والإخلاص. واختلفوا في هؤلاء الملائكة فقيل هم الحفظة وقيل غيرهم لقوله ﷺ: [فوافق قوله قول أهل السماء]: وأجاب الأولون عنه بأنه إذا قالها الحاضرون من الحفظة قالها من فوقهم حتى ينتهي إلى أهل السماء.`,
        o: `القاضي عياض: الموافقة في الصفة والخشوع والإخلاص (قول). الملائكة: الحفظة، أو غيرهم من أهل السماء.`,
        s: `وهذا قول ضعيف، لأنه لا يستطيع أحد أن يخلص كإخلاص الملائكة وخشوعهم إلا الأنبياء أعلم؛ والصحيح أن نقول في هذه المسألة (الصحيح) ولا نقول (الصواب) لأن المسألة ليست نص، والقول الثاني الذي هو وافقهم في الخشوع ليس باطلًا — الذي هو عكس الصواب — ولكنه قول مرجوح والأول أرجح لأنه بين وقت التأمين وعلل بهذه العلة وكذا بين وقت التحميد وعلل بهذه العلة وهو ظاهر الحديث ومقصوده أنه وافقهم في التوقيت. وكما قلنا أن استدلال الإمام النووي هذا حجة على الشافعية في أن المأموم يقول (ربنا ولك الحمد) لأن هنا بيان وقت وافق قوله قول الملائكة في التوقيت فينبغي أن يقول مع الإمام ليوافقوا قول الملائكة، وهذا إنها يقع إذا وافق المأموم (ربنا ولك الحمد) مباشرةً وليس (سمع الله لمن حمده) لأنه لو قال (سمع الله لمن حمده) كان تحميده بعد تحميد الإمام. (والصحيح أنه يُعمم (قالت الملائكة) والله ﷻ أعلم بها.)`,
        f: [] },
      { q: `قول ابن شهاب «كان رسول الله ﷺ يقول آمين» وفهم قراءة الفاتحة وأن التأمين لا يكون إلا عقبها`, p: `145`,
        n: `وقول ابن شهاب (وكان رسول الله ﷺ يقول آمين) معناه أن هذه صيغة تأمين النبي ﷺ وهو تفسير لقوله ﷺ: [إذا أمّن الإمام فأمّنوا] ورد لقول من زعم أن معناه إذا دعا الإمام بقوله اهدنا الصراط إلى آخرها. وفي هذا الحديث دليل على قراءة الفاتحة لأن التأمين لا يكون إلا عقبها.`,
        o: `قول من زعم أن التأمين عند دعاء الإمام بـ«اهدنا الصراط» (مردود).`,
        s: `ولذلك الصحيح أيضًا أن المأموم يقرأ الفاتحة حتى إذا قرأ ولا الضالين يقول آمين.`,
        f: [] },
    ],
  },
  {
    title: `باب ائتمام المأموم بالإمام (ص146–)`,
    items: [
      { q: `متابعة الإمام في الأفعال والتكبير، والإشارة والعمل القليل في الصلاة للحاجة`, p: `148`,
        n: `(فيه حديث أنس: سقط النبي ﷺ عن فرس فجحش شقه الأيمن... «إنما جعل الإمام ليؤتم به فإذا كبر فكبروا...»). وفيه جواز الإشارة والعمل القليل في الصلاة للحاجة. وفيه متابعة الإمام في الأفعال والتكبير. وقوله: (ربنا ولك الحمد) كذا وقع هنا [ولك الحمد] بالواو، وفي روايات بحذفها. وقد سبق أنه يجوز الأمران.`,
        o: NO_O,
        s: `فإنه أشار إليهم أن اجلسوا، فهذا دليل على جواز الإشارة والعمل القليل للحاجة، والقلة والكثرة مردها إلى العُرف. وفي الأفعال: بأن يتابع الإمام بعد أن يُتم الإمام حركته، يبدأ المأموم في الحركة، فإذا ركع ووصل إلى كمال الانحناء، يبدأ المأموم في الركوع وهكذا في السجود وسائر الحركات، ويكون التكبير بعد تكبير الإمام. ويجوز إضافة (اللهم) أيضًا.`,
        f: [] },
      { q: `وجوب متابعة المأموم للإمام في التكبير والأفعال: متى يكبر تكبيرة الإحرام، ومن سبق الإمام أو قارنه، ومن سلّم قبل الإمام`, p: `149`,
        n: `وفيه وجوب متابعة المأموم لإمامه في التكبير والقيام والقعود والركوع والسجود وأنه يفعلها بعد الإمام: فيكبّر تكبيرة الإحرام بعد فراغ الإمام منها فإن شرع فيها قبل فراغ الإمام منها لم تنعقد صلاته. ويركع بعد شروع الإمام في الركوع وقبل رفعه منه فإن قارنه أو سبقه فقد أساء ولكن لا تبطل صلاته، وكذا السجود. ويسلّم بعد فراغ الإمام من السلام فإن سلّم قبله بطلت صلاته إلا أن ينوي المفارقة ففيه خلاف مشهور. وإن سلّم معه لا قبله ولا بعده فقد أساء ولا تبطل صلاته على الصحيح وقيل تبطل.`,
        o: `إن سبق الإمام في الركوع أو قارنه: عند الجمهور لا تبطل، وقيل تبطل. من سلّم قبل الإمام: تبطل إلا أن ينوي المفارقة (خلاف مشهور).`,
        s: `أي أن المأموم لا يبدأ التكبير إلا بعد انتهاء الإمام من حرف (الراء) في [أكبر]؛ وهو قول جمهور أهل العلم، أن مسابقة الإمام أو مساواته في تكبيرة الإحرام تبطل الصلاة. لا تبطل الصلاة لأن النبي ﷺ قال: [أَمَا يَخْشَى أَحَدُكُمْ، أَوْ لاَ يَخْشَى أَحَدُكُمْ – إِذَا رَفَعَ رَأْسَهُ قَبْلَ الإِمَامِ أَنْ يَجْعَلَ اللَّهُ رَأْسَهُ رَأْسَ حِمَارٍ، أَوْ يَجْعَلَ اللَّهُ صُورَتَهُ صُورَةَ حِمَارٍ] البخاري. ولم يأمره بإعادة الصلاة، فهو دليل على أنه فعل محرم لأن العقوبة لا تكون إلا على فعل محرم ولكن لا تبطل الصلاة. إن نوى مفارقة الإمام لعذر، كأن يكون الإمام طول فيسلم ناويًا مفارقة الإمام والصحيح صحة صلاته إن كان قد أتمها أو ينوي المفارقة ويكمل هو ما بقي منها ويسلم قبل إمامه، كأن يكون الإمام من عادته أن يصلي بسورة البقرة في صلاة العشاء كما صلى الرجل خلف معاذ في صلاة الفريضة فنوى رجل المفارقة وفارق الإمام وسلم قبل الإمام، فيحتمل أنه سلم واستأنف صلاته أو أكمل الصلاة وسلم، فيجزيه ذلك وذلك. السلام أشبه بالركوع والسجود منه من تكبيرة الإحرام.`,
        f: [] },
      { q: `صلاة القادر على القيام خلف إمام قاعد: (وإذا صلى قاعدًا فصلوا قعودًا)`, p: `149–150`,
        n: `وأما قوله ﷺ: (وإذا صلى قاعدًا فصلوا قعودًا) فاختلف العلماء فيه: فقالت طائفة بظاهره، وممن قال به أحمد بن حنبل والأوزاعي رحمهما الله تعالى. وقال مالك رحمه الله تعالى في رواية لا يجوز صلاة القادر على القيام خلف القاعد لا قائمًا ولا قاعدًا. وقال أبو حنيفة والشافعي وجمهور السلف رحمهم الله تعالى لا يجوز للقادر على القيام أن يصلي خلف القاعد إلا قائمًا، واحتجوا بأن النبي ﷺ في مرض فاتاه بعد هذا قاعدًا وأبو بكر ﵁ والناس خلفه قيامًا، وإن كان بعض العلماء زعم أن أبا بكر ﵁ كان هو الإمام والنبي ﷺ مُقتدٍ به، لكن الصواب أن النبي ﷺ كان هو الإمام وقد ذكره مسلم بعد هذا الباب صريحًا أو كالصريح فقال في روايته عن أبي بكر بن أبي شيبة بإسناده عن عائشة رضي الله عنها قالت: (فجاء رسول الله ﷺ حتى جلس عن يسار أبي بكر وكان رسول الله ﷺ يصلي بالناس جالسًا وأبو بكر قائمًا يقتدي أبو بكر بصلاة النبي ﷺ ويقتدي الناس بصلاة أبي بكر).`,
        o: `أحمد والأوزاعي: يصلون خلفه قعودًا إذا ابتدأ الإمام الصلاة قاعدًا. مالك (رواية): لا يجوز للقادر على القيام أن يصلي خلف القاعد لا قائمًا ولا قاعدًا. أبو حنيفة والشافعي وجمهور السلف: لا يجوز إلا قائمًا. (وزعم بعضهم أن أبا بكر كان هو الإمام.)`,
        s: `ولكن الإمام أحمد قال: إذا عرض للإمام عارض أثناء الصلاة فجلس صلى المأموم قائمًا، وأما إذا بدأ الصلاة قاعدًا صلى المأموم قاعدًا. وهو قول مخالف سواء لأحاديث الباب أو الآتية في صلاة النبي ﷺ في مرض موته، فإبطال الصلاة للمأموم خلف الإمام القاعد ليس عليه دليل وقالوا لو صلى قاعدًا فقد خالف قوله تعالى: (وَقُومُوا لِلَّهِ قَانِتِينَ) والأحاديث التي ذكرت (إذا قمت إلى الصلاة) فقالوا القيام ركن فسيترك ركن وهو قادر عليه؛ ولو أنه صلى قائمًا خلف الإمام الجالس فقد خالف حديث: (وَإِذَا صَلَّى قَاعِدًا فَصَلُّوا قُعُودًا) فقالوا الحل ألا يصلي ويأتوا بإمام آخر، وللعلم الأحوط أن يأتوا بإمام آخر، ولكن هذا المذهب غير راجح فبطلان الصلاة مذهب ضعيف ولكن الأحوط خروجًا من الخلاف أن الإمام القاعد يستخلف وكذلك العاجز عن السجود بالأولى وكذا الركوع، فإمام يسجد بالإيماء فقط الأولى ألا يصلي إمامًا خروجًا من الخلاف، فالخلاف في هذا أشد، فقول من يبطل صلاة المأموم خلف الذي لا يسجد ولا يركع أكثر. (خلافًا لهذا الحديث وللعلم فإن هذا ظاهر صنيع مسلم، فمسلم قد أتى بأحاديث (فَصَلُّوا جُلُوسًا أَجْمَعُونَ) وعقبها بحديث الصلاة خلف النبي ﷺ في مرض موته أنهم صلوا قيامًا وسيأتي. وهذه طريقة مسلم أنه يأتي أولًا بالحديث المشكل ثم يأتي بالمبين سواء كان المشكل هذا مخصوصًا أو منسوخًا، فيأتي بالحديث المبين الذي عليه العمل مؤخرًا.) فقالوا بالنسخ، الإمام أحمد جمع بأنه هذا عرض أثناء الصلاة والحقيقة أن النبي ﷺ بدأ الصلاة جالسًا ولكنه بدأ بعدهم، وقد كنت أميل لقول الإمام أحمد رحمه الله في الجمع ولكن قول الجمهور بالنسخ قوي في الدلالة.`,
        f: [`(ص150) وهو أن يصلي القادر على القيام قاعدًا خلف الإمام القاعد.`, `(ص151) وهذا نص واضح في أن آخر الأمرين أن صلوا قيامًا خلف رسول الله ﷺ قاعدًا.`] },
      { q: `معنى «إنما جعل الإمام ليؤتم به»: هل تصح صلاة الفرض خلف النفل وعكسه، والظهر خلف العصر؟`, p: `151–152`,
        n: `وأما قوله ﷺ: (إنما جعل الإمام ليؤتم به): فمعناه عند الشافعي وطائفة في الأفعال الظاهرة وإلا فيجوز أن يصلي الفرض خلف النفل وعكسه، والظهر خلف العصر وعكسه. وقال مالك وأبو حنيفة ﵄ وآخرون لا يجوز ذلك، وقالوا معنى الحديث (ليؤتم به) في الأفعال والنيات. ودليل الشافعي ﵁ ومُوافقيه أن النبي ﷺ صلى بأصحابه ببطن نخل صلاة الخوف مرتين بكل فرقة مرة فصلاته الثانية وقعت له نفلًا وللمقتدين فرضًا، وأيضًا حديث معاذ: (كان يصلي العشاء مع النبي ﷺ ثم يأتي قومه فيصليها بهم هي له تطوع وهم فريضة)، ولهم مما يدل على أن الائتمام إنما يجب في الأفعال الظاهرة قوله ﷺ في رواية جابر ﵁: (ائتموا بأئمتكم إن صلى قائمًا فصلوا قيامًا وإن صلى قاعدًا فصلوا قعودًا). والله أعلم.`,
        o: `الشافعي وموافقوه: يجوز الفرض خلف النفل وعكسه، والظهر خلف العصر وعكسه (الائتمام في الأفعال الظاهرة). مالك وأبو حنيفة وآخرون: لا يجوز (الائتمام في الأفعال والنيات).`,
        s: `فهناك أدلة تفصيلية في ذلك منها: صلاة معاذ متنفلًا بقومه مفترضين، وصلاة الذي صلى في رحلة متنفلًا مع الإمام إذا حضرت الصلاة كما قال النبي ﷺ: (إِذَا صَلَّيْتُمَا فِي رِحَالِكُمَا ثُمَّ أَتَيْتُمَا مَسْجِدَ جَمَاعَةٍ فَصَلِّيَا مَعَهُمْ، فَتَكُونُ لَكُمَا نَافِلَةً، وَالَّتِي فِي رِحَالِكُمَا فَرِيضَةً) (هق) ٣٤٦٢، (قط) ١/ ٤١٤، انظر صحيح الجامع: ٦٦٦) فصلى النفل خلف الفرض وكذلك حديث أبي سعيد الخدري، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ "أَبْصَرَ رَجُلًا يُصَلِّي وَحْدَهُ، فَقَالَ: أَلَا رَجُلٌ يَتَصَدَّقُ عَلَى هَذَا فَيُصَلِّيَ مَعَهُ" ، (د) ٥٧٤ [قال الألباني]: صحيح، فإنه كذلك صلاة النفل خلف الفرض. أي والعصر خلف الظهر والظهر خلف العصر في الجمع لعذر وهذا عند الشافعية وطائفة من العلماء. فيكون الكلام على الأفعال وليس النيات. الصحيح قول الشافعي، ولكن إذا أقيمت الصلاة مع الإمام الراتب، الصحيح أن يصلي الصلاة التي أُقيمت، ولكن تصح الصلاة والله أعلى وأعلم.`,
        f: [`(ص152) وهذا ثابت في صحيح مسلم: (عَنْ أَبِي سَلَمَةَ عَنْ جَابِرٍ قَالَ أَقْبَلْنَا مَعَ رَسُولِ اللَّهِ ﷺ حَتَّى إِذَا كُنَّا بِذَاتِ الرِّقَاعِ... فَصَلَّى بِطَائِفَةٍ رَكْعَتَيْنِ ثُمَّ تَأَخَّرُوا وَصَلَّى بِالطَّائِفَةِ الأُخْرَى رَكْعَتَيْنِ، قَالَ فَكَانَتْ لِرَسُولِ اللَّهِ ﷺ أَرْبَعُ رَكَعَاتٍ وَلِلْقَوْمِ رَكْعَتَانِ.)`] },
    ],
  },
  {
    title: `باب النهي عن مبادرة الإمام بالتكبير وغيره (ص152–154)`,
    items: [
      { q: `النهي عن قيام الغلمان والأتباع على رأس متبوعهم الجالس، والقيام للداخل من أهل الفضل`, p: `153–154`,
        n: `قوله ﷺ: (إن كدتم تفعلون فعل فارس والروم يقومون على ملوكهم وهو قعود فلا تفعلوا): فيه النهي عن قيام الغلمان والأتباع على رأس متبوعهم الجالس لغير حاجة، وأما القيام للداخل إذا كان من أهل الفضل والخير فليس من هذا بل هو جائز قد جاءت به أحاديث وأطبق عليه السلف والخلف وقد جمعت دلائله وما يرد عليه في جزء وبالله التوفيق والعصمة.`,
        o: NO_O,
        s: `فيقومون حوله وهو جالس أمرٌ مكروه إلا أن يجلس بعضهم. هذا في القيام للسلام عليه، أما القيام المجرد فهو داخل في النهي لأن النبي ﷺ كان يكره أن يقوموا إذا رأوه داخلًا، أما أن يقوم ليسلم فنعم، فالمدرس الذي يوقف التلاميذ لا ليسلموا عليه ولا لشيء فليس هذا بمشروع، بل هو داخلٌ في النهي.`,
        f: [] },
    ],
  },
  {
    title: `باب استخلاف الإمام إذا عرض له عذر من مرض وسفر وغيرهما، وأن من صلى خلف إمام جالس لعجزه عن القيام لزمه القيام إذا قدر عليه ونسخ القعود خلف القاعد (ص154–166)`,
    items: [
      { q: `الاستخلاف في الصلاة: ما يدل عليه حديث مرض النبي ﷺ وتقديم أبي بكر، وأن الخلافة له`, p: `158`,
        n: `فيه حديث استخلاف النبي ﷺ أبا بكر ﵁ وقد قدمنا في آخر الباب السابق دليل ما ذكرته في الترجمة.`,
        o: NO_O,
        s: NO_N,
        f: [`(ص158) والحديث مع الذي قبله والذي قبله فيه تواتر النقل عن أصحاب النبي ﷺ أن رسول الله قد مات، خلافًا للضلال المبتدعين القائلين أنه لم يمت، ولا نزاع في أنه يحيى حياة برزخية عند الله ﷻ، ولكن ليس على وجه الأرض، وقد مات ﷺ ولم تأكل جسده الأرض ولا دود ولا غيره.`] },
      { q: `الغسل من الإغماء: هل هو مستحب أم واجب؟ والإغماء على الأنبياء`, p: `159`,
        n: `قولها (قال ضعوا لي ماء في المخضب ففعلنا فاغتسل) دليل الاستحباب بالغسل من الإغماء وإذا تكرر الإغماء استحب تكرر الغسل لكل مرة، فإن لم يغتسل إلا بعد الإغماء مرات كفى غسل واحد. وقد حمل القاضي عياض الغسل هنا على الوضوء من حيث إن الإغماء ينقض الوضوء ولكن الصواب أن المراد غسل جميع البدن فإنه ظاهر اللفظ ولا مانع يمنع منه فإن الغسل مستحب من الإغماء. بل قال بعض أصحابنا إنه واجب وهذا شاذ ضعيف. وقوله (فأغمي عليه) دليل على جواز الإغماء على الأنبياء صلوات الله وسلامه عليهم ولا شك في جوازه فإنه مرض والمرض يجوز عليهم بخلاف الجنون فإنه لا يجوز عليهم لأنه نقص والحكمة في جواز المرض عليهم ومصائب الدنيا تكثير أجرهم وتسلية الناس بهم ولئلا يفتتن الناس بهم ويعبدوهم لما يظهر عليهم من المعجزات والآيات البينات والله أعلم.`,
        o: `بعض الشافعية: الغسل من الإغماء واجب (شاذ ضعيف). القاضي عياض: المراد الوضوء.`,
        s: `الغسل من الإغماء مستحب وليس بواجب؛ ولم ينقل بالوجوب لأن الأفعال لا يلزم منها الوجوب (ولأنه ليس بأمر).`,
        f: [] },
      { q: `تأخر الإمام عن أول الوقت وانتظار المصلين له`, p: `159`,
        n: `قولها (فقال أصلى الناس فقيل لا وهم ينتظرونك يا رسول الله) دليل على أنه إذا تأخر الإمام عن أول الوقت ورجي مجيئه على قرب ينتظر ولا يتقدم غيره وسنبسط المسألة في الباب بعده إن شاء الله تعالى.`,
        o: NO_O,
        s: NO_N,
        f: [] },
      { q: `قول عائشة «أنت أحق بذلك» وفوائد حديث الاستخلاف: فضل أبي بكر ثم عمر، ومراجعة عائشة النبي ﷺ، ومعنى «إنكن لأنتن صواحب يوسف»`, p: `160–164`,
        n: `قولها (فأرسل رسول الله ﷺ إلى أبي بكر ﵁ أن يصلي بالناس فقال أبو بكر ﵁ وكان رجلًا رقيقًا يا عمر صل بالناس فقال عمر ﵁ أنت أحق بذلك) فيه فوائد: منها فضيلة أبي بكر الصديق ﵁ وترجيحه على جميع الصحابة رضوان الله عليهم أجمعين وتفضيله وتنبيه على أنه أحق بخلافة رسول الله ﷺ من غيره. ومنها أن الإمام إذا عرض له عذر عن حضور الجماعة استخلف من يصلي بهم وأنه لا يستخلف إلا أفضلهم. ومنها فضيلة عمر بعد أبي بكر ﵁ لأن أبا بكر ﵁ لم يعدل إلى غيره. ومنها أن المفضول إذا عرض عليه الفاضل مرتبة لا يقبلها بل يدعها للفاضل إذا لم يمنع مانعٌ. ومنها جواز الثناء في الوجه لمن أمن عليه الإعجاب والفتنة لقوله (أنت أحق بذلك). وأما قول أبي بكر لعمر ﵁ ما صل بالناس فقاله للعذر المذكور وهو أنه رجل رقيق القلب كثير الحزن والبكاء لا يملك عينيه، وقد تأوله بعضهم على أنه قاله تواضعًا والمختار ما ذكرناه. وقولها (فخرج بين رجلين أحدهما العباس) وفسر ابن عباس الآخر بعلي بن أبي طالب وفي الطريق الآخر (فخرج ويد له على الفضل بن عباس ويد له على رجل آخر) وجاء في غير مسلم بين رجلين أحدهما أسامة بن زيد، وطريق الجمع بين هذا كلها أنهم كانوا يتناوبون الأخذ بيده الكريمة تارة هذا وتارة ذاك ويتنافسون في ذلك وهؤلاء هم خواص أهل بيته الرجال الكبار وكان العباس ﵁ أكثرهم ملازمة للأخذ بيده الكريمة المباركة ﷺ أو أنه أدام الأخذ بيده وإنما يتناوب الباقون في اليد الأخرى وأكرموا العباس باختصاصه بيد واستمرارها له لما له من السن والعمومة وغيرهما ولهذا ذكرته عائشة رضي الله عنها مسمى وأبهمت الرجل الآخر إذ لم يكن أحد الثلاثة الباقين ملازمًا في جميع الطريق ولا معظمه بخلاف العباس والله أعلم. وقوله ﷺ: (أجلساني إلى جنبه فأجلساه إلى جنبه) فيه جواز وقوف مأموم واحد بجنب الإمام لحاجة أو مصلحة كإسماع المأمومين وضيق المكان ونحو ذلك. وقوله (استأذن أزواجه أن يمرض في بيتها) يعني بيت عائشة وهذا يستدل به من يقول كان القسم واجبًا على النبي ﷺ بين أزواجه في الدوام كما يجب في حقنا ولأصحابنا وجهان: أحدهما هذا، والثاني سنة ويحملون هذا وقوله ﷺ [اللهم هذا قسمي فيما أملك] على الاستحباب ومكارم الأخلاق وجميل العشرة. وفيه فضيلة عائشة رضي الله عنها ورجحانها على جميع أزواجه الموجودات ذلك الوقت وكن تسعًا إحداهن عائشة رضي الله عنها وهذا لا خلاف فيه بين العلماء وإنما اختلفوا في عائشة وخديجة رضي الله عنهما. قوله: (يخط برجليه في الأرض) أي لا يستطيع أن يرفعهما ويضعهما ويعتمد عليهما. قوله ﷺ: (إنكن لأنتن صواحب يوسف) أي في التظاهر على ما تردن وكثرة إلحاحكن في طلب ما تردنه وتملن إليه، وفي مراجعة عائشة جواز مراجعة ولي الأمر على سبيل العرض والمشاورة والإشارة بما يظهر أنه مصلحة وتكون تلك المراجعة بعبارة لطيفة ومثل هذه المراجعة مراجعة عمر ﵁ في قوله [لا تبشرهم فيتكلوا] وأشباهه كثيرة مشهورة.`,
        o: `قيل إن قول أبي بكر لعمر كان تواضعًا؛ المختار أنه للعذر المذكور (رقة القلب وكثرة البكاء). وفي القسم بين الأزواج على النبي ﷺ وجهان عند الشافعية: واجب أو سنة. واختلف في تفضيل عائشة وخديجة رضي الله عنهما.`,
        s: `والصحيح أنه كان سنة لقوله تعالى: (تُرْجِي مَن تَشَاءُ مِنْهُنَّ وَتُؤْوِي إِلَيْكَ مَن تَشَاءُ وَمَنِ ابْتَغَيْتَ مِمَّنْ عَزَلْتَ فَلَا جُنَاحَ عَلَيْكَ) فالصحيح أن القسم لم يكن واجبًا عليه ﷺ وإنما كان يفعله من باب مكارم الأخلاق، وأما في حق غيره ففرض. والصحيح أن خديجة أفضل لقوله ﷺ: («خَيْرُ نِسَائِهَا مَرْيَمُ بِنْتُ عِمْرَانَ وَخَيْرُ نِسَائِهَا خَدِيجَةُ بِنْتُ خُوَيْلِدٍ». قَالَ أَبُو كُرَيْبٍ وَأَشَارَ وَكِيعٌ إِلَى السَّمَاءِ وَالأَرْضِ.) مسلم. وأما مراجعة عائشة: بل الظاهر ما ذكرنا من إبداء أمر وإخفاء غيره لأن صواحب يوسف أبدين عتاب امرأة العزيز وكان كيدًا منهن لأمر آخر وهو رؤية يوسف، فعائشة أظهرت أنها تريد أن تُسمع الناس لأن أبا بكر رجل رقيق وهي إنها كانت تكره أن يتشاءم الناس بأبيها. وعائشة رضي الله عنها إنما اقترحت أن يؤم الناس عمر ﵁ لكراهيتها أن يتشاءم الناس بمن يقوم مقام النبي ﷺ، فأرادت كفطرة أن تنجي أباها وقد عُتبت على ذلك وشُبهت بالنسوة صواحب يوسف في إبداء أمر وإخفاء غيره، وهذا التشبيه في نفسه نوع عتاب ومنقصة، فهذا الأمر كان منها غير سديد رضي الله عنها، ولا شك أن أمر عمر ﵁ أن يصلي بالناس وفي القوم أبي بكر أمر غير سديد واقتراح غير صائب فضلًا أن يكون غرضه ما ذكرت رضي الله عنها قالت: [ وَمَا حَمَلَنِي عَلَى كَثْرَةِ مُرَاجَعَتِهِ إِلاَّ أَنَّهُ لَمْ يَقَعْ فِي قَلْبِي أَنْ يُحِبَّ النَّاسُ بَعْدَهُ رَجُلاً قَامَ مَقَامَهُ أَبَدًا وَإِلاَّ أَنِّي كُنْتُ أَرَى أَنَّهُ لَنْ يَقُومَ مَقَامَهُ أَحَدٌ إِلاَّ تَشَاءَمَ النَّاسُ بِهِ فَأَرَدْتُ أَنْ يَعْدِلَ ذَلِكَ رَسُولُ اللَّهِ ﷺ عَنْ أَبِي بَكْرٍ. ] وكان ظن رسول الله ﷺ بأصحابه خيرًا من ظن عائشة بهم، فقد قام أبو بكر فقدمه الصحابة وأحبوه بعد رسول الله ﷺ أشد أحد حبًّا بعد رسول الله ﷺ، وهكذا واجب على كل مكلف أن يُحب أبا بكر ﵁ بعد رسول الله ﷺ أشد من حب أي أحد، وذلك لأن الله ﷻ جعله صاحب رسول الله ﷺ المقرب إليه واختاره ﷺ وأمر أن يصلي بالناس. قوله: (إِنَّكُنَّ لأَنْتُنَّ صَوَاحِبُ يُوسُفَ) فهذا دليل على أن صواحب يوسف أردن بقولهن: (إِنَّا لَنَرَاهَا فِي ضَلاَلٍ مُبِينٍ) أن يرون يوسف لذا قال ﷻ: (فَلَمَّا سَمِعَتْ بِمَكْرِهِنَّ) فأين المكر في ذلك أن يتكلم النسوة عن ذم من تحب فتاها، المكر في ذلك أنهن تكلمن بذلك يُظهرن الإنكار عليها وحقيقة الأمر موافقتها في طلب رؤية يوسف والتمتع بوجهه، فشبه النبي ﷺ إرادة عائشة أمرًا وإخفاء أمر آخر والله أعلم بهذا أرادت حفصة أيضًا في العتاب (إِنَّكُنَّ) فشبه النبي ﷺ إرادتهن أمرًا وإخفائهن غيره بها صنع النسوة بأنهن أظهرن الإنكار وغرضهن الموافقة والمراودة وغرضهن أن يفعلن ما فعلت من الحب ومن النظر إلى يوسف ﷺ والله أعلم. وهذا دليل على أن التشبيه لا يلزم أن يكون فيه كل الجوانب متفقة، فقد شبههن ﷺ صراحةً (إِنَّكُنَّ لأَنْتُنَّ صَوَاحِبُ يُوسُفَ) ومعلومٌ أن عائشة رضي الله عنها وحفصة رضي الله عنها أكرم بها لا يعلمه إلا الله من صواحب يوسف، ولكن التشبيه يمكن أن يقع في جزئية معينة وفي فعل معين ولو من بعيد ولا يلزم في التشبيه المساواة. وهذه الروايات صريحة في أن النبي ﷺ كان هو الإمام، وإليها ذهب الجمهور في كون هذا الحديث ناسخ للأحاديث الواردة في (صلوا قعودًا أجمعون) في أنهم يصلون قعودًا خلف الإمام الجالس، فقد كان النبي ﷺ إمامًا جلس على يسار أبي بكر وقد كان أبو بكر يبلغ صلاة النبي ﷺ للناس، فكان يبلغ عنه فقط. وفي قول عروة: (فَجَلَسَ رَسُولُ اللَّهِ حِذَاءَ أَبِي بَكْرٍ إِلَى جَنْبِهِ.) صريح أيضًا في أن المأموم يقف إلى جنب الإمام لا يتأخر عنه قليلًا كما يفعل البعض، فيتأخرون عن الإمام إذا كان رجل يؤم رجلًا، فالصحيح أن يقف بحذائه يقف بجواره تمامًا لا يتأخر ولا يتقدم. وفيه مشروعية التبليغ عن الإمام إذا لم يصل صوت الإمام إلى الناس لعذر.`,
        f: [`(ص161–162) «في أن صواحب يوسف أبدين عتاب امرأة العزيز وكان كيدًا منهن لأمر آخر وهو رؤية يوسف»: (بيان وجه الشبه بين عائشة وحفصة وصواحب يوسف). وأن التشبيه لا يلزم أن يكون في كل الجوانب.`, `(ص163) وقول عائشة رضي الله عنها: [فَأَنْفَذَتْ قُرَيْشٌ جِوَارَ ابْنِ الدَّغِنَةِ...] صحيح البخاري؛ استشهاد بأن قراءة أبي بكر ﵁ كانت تؤثر في الناس لرقته ولذلك اعتذر بأنه «رجل أسيف».`] },
      { q: `الأخذ بيد الإمام والتبليغ عن الإمام، وحكم التفات المصلي لحاجة، ومخاطبة المصلي بالإشارة`, p: `164–165`,
        n: `قولها (يهادى بين رجلين) أي يمشي بينهما متكئًا عليهما يتمايل إليهما. قوله (كأن وجهه ورقة مصحف) عبارة عن الجمال البارع وحسن البشرة وصفاء الوجه واستنارته... قوله (ثم تبسم رسول الله ﷺ ضاحكًا) سبب تبسمه ﷺ فرحه بما رأى من اجتماعهم على الصلاة واتباعهم لإمامهم وإقامتهم شريعته واتفاق كلمتهم واجتماع قلوبهم ولهذا استنار وجهه ﷺ على عادته إذا رأى أو سمع ما يسره يستنير وجهه. وفيه معنى آخر وهو تأنيسهم وإعلامهم بتأتي حاله في مرضه. وقيل يحتمل أنه ﷺ خرج ليصلي بهم فرأى من نفسه ضعفًا فرجع. قوله (ونكص) أي رجع إلى وراءه قهقرى.`,
        o: NO_O,
        s: `والأظهر الأول، ويؤنسهم ويُعلمهم أنه بخير وأنه يريد أن يبقوا كما هم مجتمعي الكلمة متفقين على إمام، يقيمون عبادة الله ﷻ وشرعه من بعده ﷺ في غيابه كما كانوا في حضوره. الظاهر والله أعلى وأعلم أن النبي ﷺ إنما كشف الستارة ليطمئن عليهم ورأى ما يطمئنه وسُر بذلك ﷺ لما رأى انتظامهم في الصفوف، فأشار إليهم أن أكملوا صلاتكم. أي دون أن يلتفت فنكص على عقبيه ووجهه إلى القبلة. وهذا الحديث دليل على جواز الالتفات في الصلاة للحاجة فإنهم بان ووضح لهم وجه رسول الله ﷺ وهم في الصلاة والرسول ﷺ في حجرته، إذًا قد نظروا إلى وجه رسول الله ﷺ في الصلاة، وهذا دليل على أنه يجوز أن يلتفت التفاته لا ينحرف بها عن القبلة وإنما يلتفت التفاتة يسيرة ينظر به للحاجة، وأي حاجة أفضل من أن ينظروا إلى وجه رسول الله ﷺ النظرة الأخيرة. وفيه حب الصحابة ﵁ للنبي ﷺ حبًّا عظيمًا أعظم الحب لمخلوق. وفيه جواز مخاطبة المصلي في الصلاة بالإشارة لأن النبي ﷺ [فَأَوْمَأَ نَبِيُّ اللَّهِ ﷺ بِيَدِهِ إِلَى أَبِى بَكْرٍ أَنْ يَتَقَدَّمَ] و[فَأَشَارَ إِلَيْهِمْ رَسُولُ اللَّهِ ﷺ بِيَدِهِ أَنْ أَتِمُّوا صَلاَتَكُمْ] فيجوز أن تخاطب المصلي بالإشارة لأمر لإصلاح صلاته وفعل المشروع فيها وهذا هو الأولى من أن تخاطبه كلامًا، وإن جاز ذلك كما قالت أسماء في حديث الكسوف آية فقالت برأسها أي نعم، فيجوز أن يخاطب بالكلام والأولى أن يخاطب بالإشارة إذا كان المخاطب ليس في الصلاة، أما المصلي فلا يتكلم بل يشير إذا احتاج إلى ذلك. (وفيه معنى آخر تأنيسهم وإعلامهم بتأتي حاله في مرضه.)`,
        f: [`(ص165) ويحتمل أن النبي ﷺ كشف الستارة ليطمئن عليهم ورأى ما يطمئنه. (تعليقًا على قول النووي: «وقيل يحتمل أنه ﷺ خرج ليصلي بهم فرأى من نفسه ضعفًا فرجع».) وقوله «وَضَحَ لَنَا وَجْهُهُ» أي بان وظهر.`] },
      { q: `رفع الصوت بالتكبير للإسماع واقتداء المأموم بصوت المبلّغ، وصحة صلاة المبلّغ والسامع`, p: `166`,
        n: `قولها (وأبو بكر يسمع الناس التكبير) فيه جواز رفع الصوت بالتكبير ليسمعه الناس ويتبعوه. وأنه يجوز للمقتدي اتباع صوت المكبّر وهذا مذهبنا ومذهب الجمهور، ونقلوا فيه الإجماع وما أراه يصح الإجماع فيه فقد نقل القاضي عياض عن مذهبهم فمنهم من أبطل صلاة المقتدي ومنهم من لم يبطلها، ومنهم من قال إن أذن الإمام في الإسماع صح الاقتداء به وإلا فلا ومنهم من أبطل صلاة المسمع ومنهم من صححها ومنهم من شرط إذن الإمام ومنهم من قال إن تكلف صوتًا بطلت صلاته وصلاة من ارتبط بصلاته، وكل هذا ضعيف والصحيح جواز كل ذلك وصحة صلاة المُسمع والسامع ولا يعتبر إذن الإمام. والله أعلم.`,
        o: `قول المالكية (نقله القاضي عياض): منهم من أبطل صلاة المقتدي، ومنهم من لم يبطلها، ومنهم من شرط إذن الإمام، ومنهم من أبطل صلاة المسمع.`,
        s: `قوله: (نقل القاضي عياض عن مذهبهم) أي المالكية، والصحيح أنها لا تبطل بل مشروعة. طالما وجدت الحاجة، أما إذا لم توجد حاجة فقد أساء المبلغ وصلاته صحيحة لأنه لا دليل على بطلان صلاته، ولا ينبغي الاعتماد على صوته دون صوت الإمام طالما وصل صوت الإمام.`,
        f: [] },
    ],
  },
  {
    title: `باب تقديم الجماعة من يصلي بهم إذا تأخر الإمام ولم يخافوا مفسدةً بالتقديم (ص166–171)`,
    items: [
      { q: `فوائد حديثي تقديم أبي بكر وعبد الرحمن بن عوف: الإصلاح بين الناس، وتقدم غير الإمام الراتب إذا تأخر، والالتفات في الصلاة للحاجة`, p: `168–169`,
        n: `فيه حديث تقديم أبي بكر ﵁ وحديث تقدم عبد الرحمن بن عوف ﵁. فيه فضل الإصلاح بين الناس ومشي الإمام وغيره في ذلك، وأن الإمام إذا تأخر عن الصلاة تقدم غيره إذا لم يخف فتنة وإنكار من الإمام. وفيه أن المقدم نيابة عن الإمام يكون أفضل القوم وأصلحهم لذلك الأمر وأقومهم به. وفيه أن المؤذن وغيره يعرض التقدم على الفاضل وأن الفاضل يوافقه. وفيه أن الفعل القليل لا يبطل الصلاة لقوله (صفق الناس). وفيه جواز الالتفات في الصلاة للحاجة، واستحباب حمد الله تعالى لمن تجددت له نعمة ورفع اليدين بالدعاء وفعل ذلك الحمد والدعاء عقب النعمة وإن كان في صلاة. وفيه جواز مشي الخطوة والخطوتين في الصلاة. وفيه أن هذا القدر لا يكره إذا كان لحاجة. وفيه جواز استخلاف المصلي بالقوم من يتم الصلاة لهم وهذا هو الصحيح في مذهبنا. وفيه أن التابع إذا أمره المتبوع بشيء وفهم منه إكرامه بذلك الشيء لا تحتم الفعل فله أن يتركه ولا يكون هذا مخالفة للأمر بل يكون أدبًا وتواضعًا وتحذقًا في فهم المقاصد. وفيه ملازمة الأدب مع الكبار. وفيه أن السنة لمن نابه شيء في صلاته كإعلام من يستأذن عليه وتنبيه الإمام وغير ذلك أن يسبح إن كان رجلًا فيقول سبحان الله وأن تصفق وهو التصفيح إن كانت امرأة فتضرب بطن كفها اليمنى على ظهر كفها اليسرى ولا تضرب بطن كف على بطن كف على وجه اللعب واللهو فإن فعلت هكذا على جهة اللعب بطلت صلاتها لمنافاتها الصلاة.`,
        o: NO_O,
        s: `(حمد الله ورفع اليدين بالدعاء) فلو سمع إنسان بنعمة من عند الله أثناء صلاته فليرفع يديه بالحمد والدعاء لله ﷻ. (مشي الخطوة والخطوتين) لأن أبو بكر (رَجَعَ الْقَهْقَرَى) ويمكن أن يكون أكثر من خطوتين لعدم وجود نص بأنهم خطوتين اثنتين حتى وقف في الصف، وبين الصف وبين مقام النبي ﷺ ثلاثة أذرع، فهذه ربما احتاجت إلى ثلاث خطوات. (استخلاف المصلي) وذلك إذا عرض له طارئ، لأن هذا الحديث يتضمن صلاة صلوا جزء منها بإمام وجزء منها بإمام آخر، الجزء الأول مؤتمين بأبي بكر والجزء الثاني مؤتمين برسول الله ﷺ، فهذا دليل على أنه لا تُكره صلاةً بإمامين لعذر ومثلها الاستخلاف: فالإمام عرض له طارئ صلوا خلفه ثم انتقض وضوءه مثلًا فقدم من يصلي بهم، كما فعل عمر ﵁ فأقصاها أن يصلوا صلاةً بإمامين. ويستدل به على أن من بدأ في الصلاة ثم جاءت جماعة فبدأوا صلاة الجماعة وأنه طالما في نفس الركعات فليدخل معهم ولا يخرج من صلاته بل يأتم بالإمام. (لا تحتم الفعل) لأن أبي بكر أعتذر عن أن يتقدم بين يدي رسول الله ﷺ وهو أمر محبوب للنبي ﷺ هذا الأدب، وقد فهم أبو بكر من الأمر بقرينة السياق أنه أمر إباحةٌ لا أمر إيجاب ولا حتى استحباب. (إذا فعلت على جهة اللعب بطلت) هذا فيما إذا كان على وجه اللعب أما إذا كانت جاهلة أو كانت تظن أن هذا هو التصفيق الجائز صحة صلاتها. (إذا أخطأ الإمام في عدد الركعات يمكن للمأمومين أن يشيرون له بأصابعهم (ثلاثة، أربعة) فلو أخطأ فيه دون أن يتكلموا، هذا هو الأصل؛ وإنها أجاز بعض أهل العلم الكلام، إذا لم تُصلح الصلاة إلا بالكلام، وأما إذا أمكن أن تُصلح بغير الكلام لم يجز الكلام عن من قال به فضلًا عن غيرهم ممن يرى بطلان الصلاة بالكلام ولو لإصلاحها، والأظهر أنها لو كانت لإصلاح الصلاة صح ذلك.)`,
        f: [`(ص168) لأنه كان معه بعض الصحابة. (تعليقًا على «مشي الإمام وغيره في الإصلاح».)`, `(ص169) فالمسافة بين مكان الصلاة وبين حجرة النبي ﷺ أو آخر الصف الأول يسيرة، يمكن التفات يسير لا ينحرف به الإنسان عن القبلة.`] },
      { q: `الإقامة: متى تصح؟ ومن الذي يقيم؟ وإقامة غير المؤذن`, p: `170`,
        n: `وفيه أن الإقامة لا تصح إلا عند إرادة الدخول في الصلاة لقوله: (أتصلي فأقيم). وفيه أن المؤذن هو الذي يقيم الصلاة فهذا هو السنة، ولو أقام غيره كان خلاف السنة ولكن يُعتد بإقامته عندنا وعند جمهور العلماء.`,
        o: NO_O,
        s: `فهذا دليل أن هذا هو السنة، ولكن لو حدث تأخر فأقاموا الصلاة وحدث طارئ فأخروها قليلًا لا يضر والصلاة صحيحة والإقامة صحيحة ولا تُعاد. (المؤذن هو الذي يقيم) لأن بلال هو الذي جاء إلى أبي بكر ﵁.`,
        f: [] },
      { q: `اختراق الإمام الصفوف لموضعه، ودخول الداخل في الصف الأول وخرق الصفوف، واقتداء المصلي بمن أحرم بالصلاة بعده`, p: `170`,
        n: `وفيه جواز خرق الإمام الصفوف ليصل إلى موضعه إذا احتاج إلى خرقها لخروجه لطهارة أو رعاف أو نحوهما ورجوعه وكذا من احتاج إلى الخروج من المأمومين لعذر وكذا له خرقها في الدخول إذا رأى قدّامهم فُرجةً فإنهم مقصّرون بتركها. واستدل به أصحابنا على جواز اقتداء المصلي بمن يحرم بالصلاة بعده فإن الصديق ﵁ أحرم بالصلاة أولًا ثم اقتدى بالنبي ﷺ حين أحرم بعده هذا هو الصحيح في مذهبنا. وقوله (ورجع القهقرى) فيه أن من رجع في صلاته لشيء يكون رجوعه إلى وراء ولا يستدبر القبلة ولا يتحرفها.`,
        o: NO_O,
        s: NO_N,
        f: [] },
      { q: `الفوائد من حديث عبد الرحمن بن عوف: الاستعانة بصب الماء في الوضوء، لبس الجباب الرومية، المسح على الخفين، تأخر الإمام المستخلف ومخالفة الإمام الراتب`, p: `170–171`,
        n: `وأما حديث عبد الرحمن بن عوف ﵁ فقد تقدم شرحه في كتاب الطهارة وما فيه: حمل الإداوة مع الرجل الجليل. وجواز الاستعانة بصب الماء في الوضوء، وغسل الكفين في أوله ثلاثًا. وجواز لبس الجباب. وجواز إخراج اليد من أسفل الثوب إذا لم يتبين شيء من العورة. وجواز المسح على الخفين، وغير ذلك مما سبق بيانه في موضعه والله تعالى أعلم.`,
        o: NO_O,
        s: `(الاستعانة) فيصب أحد عليه الماء فلا يُكره ذلك خلافًا لبعض المتأخرين. وهذه الفائدة مأخوذة من أن المغيرة ابن شعبة أهراق الماء وصبه على النبي ﷺ ليتوضأ. (وجواز لبس الجباب) وهو جمع (جُبة) وهو ثوب مفتوح من أمام وله كمان وفي هذا الحديث فيه أنه جبة رومية، فيستدل به على جواز لبس الملابس المشتركة بين المسلمين والكفار ولو صُنعت في بلاد الكفار، ولو كان تفصيلها على ما تعود الكفار، وقد سُميت جُبة شامية أو رومية وكلاهما واحد لأن الشام كانت في أيدي الروم، فقد لبس النبي ﷺ الملابس التي صنعت في بلاد الكفار. في هذا الحديث لم يقبل النبي ﷺ بتأخير عبد الرحمن بن عوف لأنه قد قضى ركعة، فدل ذلك على أن المشروع من تأخر النبي ﷺ المستخلف إذا حضر الإمام الراتب إنها إذا كان في الركعة الأولى، وأما إذا فاتهم شيء من الصلاة فيقع اختلاف على الإمام، إذا تقدم الإمام الراتب وقد نهى النبي ﷺ عن ذلك، فدل ذلك على عدم مشروعية تأخر الإمام المستخلف إذا كان قد صلى ركعة فما فوقها لأنه سيترتب على ذلك الاختلاف على الإمام. ومن هنا نأخذ عدم مشروعية صلاة خلف إمام يصلي صلاةً غيرها يترتب عليها مخالفة الإمام كما هو قول جمهور أهل العلم كمن يصلي المغرب خلف العشاء أو العشاء خلف صلاة الكسوف مثلًا أو غير ذلك مما يترتب عليه مخالفة في الهيئة فإما أن يخالف الإمام وإما أن تفسد صلاته فيزيد فيها أو يُنقص منها، وهذا بخلاف أمر أبي بكر فإنه تراجع لأنه كان في أول ركعة، وأقره النبي ﷺ على ذلك وصلى النبي ﷺ إماماً. وفيه صلاة المسبوق أنه يُتم صلاته بعد صلاة الإمام. وفيه فضيلة الصلاة لوقتها أي في أول وقتها، وشفقة النبي ﷺ على أصحابه إذ هدأ من فزعهم لما رأوه ﷺ وقد صلى مأمومًا. وفيه فضيلة عبد الرحمن بن عوف ﵁ إذ صلى إمامًا برسول الله ﷺ، فقد صلى النبي ﷺ خلف بعض أمته.`,
        f: [] },
    ],
  },
  {
    title: `باب تسبيح الرجل وتصفيق المرأة إذا نابهما شيء في الصلاة (ص172–)`,
    items: [
      { q: `إشارة المأمومين للإمام عند السهو في عدد الركعات، وحكم الكلام لإصلاح الصلاة`, p: `172`,
        n: `(حديث: «التسبيح للرجال والتصفيق للنساء» زاد في الصلاة؛ وقال ابن شهاب: ورأيت رجالًا من أهل العلم يسبّحون ويشيرون.)`,
        o: `بعض أهل العلم: يجوز الكلام لإصلاح الصلاة إذا لم تُصلح إلا بالكلام؛ ومن الفقهاء من يرى بطلان الصلاة بالكلام ولو لإصلاحها.`,
        s: `فلو أخطأ الإمام في عدد الركعات يمكن للمأمومين أن يشيرون له بأصابعهم (ثلاثة، أربعة) فلو أخطأ فيه دون أن يتكلموا، هذا هو الأصل؛ وإنما أجاز بعض أهل العلم الكلام، إذا لم تُصلح الصلاة إلا بالكلام، وأما إذا أمكن أن تُصلح بغير الكلام لم يجز الكلام عن من قال به فضلًا عن غيرهم ممن يرى بطلان الصلاة بالكلام ولو لإصلاحها، والأظهر أنها لو كانت لإصلاح الصلاة صح ذلك. وأما عن كيفية إدراك الإمام إشارة المأمومين: بالتفاته التفاته يسيرة فيدرك ذلك، أو يكون الإمام سلم والتفت والمأمومين لم يسلموا بعد لأنه قد سلم في غير الموضع كأن سلم في ركعتين (فإنهم لا يقولوا [اثنين]، ولا يقولوا [نحن في الركعة الثانية] ولا [اتينا بركعتين وباقي اثنين]) بل يشيرون له. إذا سلم الإمام من ركعتين لم يسلم المأمومون بل يسبحون له ويشيرون حتى ينتبه فيكبر من جديد ويصلي بهم الركعتين أو ما نقص من صلاته ثم يسجد للسهو على زيادة السلام.`,
        f: [] },
      { q: `التصفيق للرجال خارج الصلاة`, p: `173`,
        n: `قوله ﷺ: (التسبيح للرجال والتصفيق للنساء) تقدم شرحه في الباب قبله.`,
        o: NO_O,
        s: `التصفيق للرجال خارج الصلاة إن كان لتنبيه أو غير ذلك فلم يرد نهي فيها أعلم، وأما إن كان لتشجيع أو غير ذلك فهذا من بدع الكفار فلا يُتشبه بهم.`,
        f: [] },
    ],
  },
  {
    title: `باب الأمر بتحسين الصلاة وإتمامها والخشوع فيها (ص173–175)`,
    items: [
      { q: `رؤية النبي ﷺ من وراء ظهره: هل هي رؤية حقيقية بالعين؟`, p: `174`,
        n: `قوله ﷺ: (يا فلان ألا تحسن صلاتك ألا ينظر المصلي إذا صلى كيف يصلي فإنما يصلي لنفسه إني والله لأبصر من ورائي كما أبصر من بين يدي) ... (أقيموا الركوع والسجود فوالله إني لأراكم من بعدي إذا ركعتم وسجدتم) قال العلماء معناه: أن الله تعالى خلق له ﷺ إدراكًا في قفاه يُبصر به من ورائه وقد انخرقت العادة له ﷺ بأكثر من هذا وليس يمنع من هذا عقل ولا شرع بل ورد الشرع بظاهره فوجب القول به. قال القاضي: قال أحمد بن حنبل رحمه الله تعالى وجمهور العلماء هذه الرؤية رؤية بالعين حقيقةً.`,
        o: `القاضي عياض: قال أحمد وجمهور العلماء: هذه الرؤية رؤية بالعين حقيقةً. وقيل: خلق الله له إدراكًا في قفاه.`,
        s: `وذلك باتساع أفق عين النبي ﷺ حيث يرى بعينه من وراء ظهره ﷺ.`,
        f: [] },
      { q: `الحلف بالله تعالى من غير ضرورة، وحلف النبي ﷺ لتأكيد الأمور المهمة`, p: `174`,
        n: `وفيه: الأمر بإحسان الصلاة والخشوع وإتمام الركوع والسجود. وجواز الحلف بالله تعالى من غير ضرورة، لكن المستحب تركه إلا لحاجة كتأكيد أمر وتفخيمه والمبالغة في تحقيقه وتمكينه من النفوس، وعلى هذا يُحمل ما جاء في الأحاديث من الحلف.`,
        o: NO_O,
        s: `لأنه قال: [إِنِّي وَاللَّهِ لأُبْصِرُ مَنْ وَرَائِي]، وقال: [فَوَاللَّهِ مَا يَخْفَى عَلَيَّ رُكُوعُكُمْ]، وقال: [وَالَّذِي نَفْسُ مُحَمَّدٍ بِيَدِهِ] ولم يُطلب منه حلف ﷺ، ولكن حلف ليؤكد الكلام. فيحلف في الأمور العظيمة المهمة ليؤكدها، ويستحب ترك الحلف في الأمور غير المهمة. فيكون حلف النبي ﷺ كله لتأكيد الأمور المهمة في النفوس وتقرير حقيقتها، والنهي عن كثرة الحلف في غير المهم كما ذكرنا، وتحريم الحلف الكاذب.`,
        f: [] },
      { q: `الرؤية «من بعدي» ومعنى «إني لأراكم من بعدي»`, p: `175`,
        n: `وقوله ﷺ: (إني لأراكم من بعدي) أي: [من ورائي] كما في الروايات الباقية. قال القاضي عياض: وحمله بعضهم على بعد الوفاة وهو بعيد عن سياق الحديث.`,
        o: `بعضهم: المراد بعد الوفاة (بعيد عن السياق).`,
        s: `نعم فهو بعيد عن سياق الحديث وعن المعنى وعن نصوص الأدلة في أن النبي ﷺ في الحديث: [فَأَقُولُ يَا رَبِّ أَصْحَابِي فَيُقَالُ لاَ تَدْرِي مَا أَحْدَثُوا بَعْدَكَ] البخاري. فهو ﷺ لا يراهم بعد وفاته لأنه لو كان يراهم بعدَ وفاته لعلم ما أحدثوه بعده إلا أن يُعلمه الله أو يُريه الله ما شاء ﷺ.`,
        f: [] },
    ],
  },
  {
    title: `باب النهي عن سبق الإمام بركوع أو سجود ونحوهما (ص175–177)`,
    items: [
      { q: `مسابقة المأموم للإمام في الأفعال: حكمها (تحريم أم كراهة) وهل تبطل الصلاة؟ وإذا نوى المفارقة`, p: `175–177`,
        n: `قوله ﷺ: (لا تسبقوني بالركوع ولا بالسجود ولا بالقيام ولا بالانصراف) فيه تحريم هذه الأمور وما في معناها والمراد بالانصراف السلام. ... وقوله ﷺ: (أما يخشى الذي يرفع رأسه قبل الإمام أن يحول الله رأسه رأس حمار) وفي رواية (صورته في صورة حمار) وفي رواية (وجهه وجه حمار) هذا كله بيان لغلظ تحريم ذلك. والله أعلم.`,
        o: `بعض العلماء: تكره المسابقة وتحرم المساواة. وبعضهم: تبطل الصلاة بالمسابقة (مثل تكبيرة الإحرام قبل الإمام).`,
        s: `فهذا العقاب إما أن يجعله الله ﷻ في الدنيا ويكون كما وردت في الأحاديث بوجود المسخ في آخر الزمان: [عَنِ النَّبِيِّ ﷺقَالَ: بَيْنَ يَدَيِ السَّاعَةِ مَسْخٌ، وَخَسْفٌ، وَقَذْفٌ]. سنن ابن ماجة. والله أعلى وأعلم. أو أن يجعله يوم القيامة كذلك فإذا قام يكون وجهه في صورة حمار أو وجهه وجه حمار نعوذ بالله من ذلك، لأن الحمار قليل الفهم، فالذي يرفع رأسه قبل الإمام في صلاة الجماعة قليل الفهم قد خالف الأمر الواجب عليه في متابعة الإمام وسبقه، ولكن هذا الحديث يدل على عدم بطلان الصلاة لأنه يظهر أن ذلك قد وقع من بعضهم بدليل قوله ﷺ: "يَا فُلاَنُ أَلاَ تُحْسِنُ صَلاَتَكَ" فهذا يدل على أنه قد خالف فيها ومع ذلك لم يأمره بالإعادة، ولكن ذكر الوعيد الشديد، دل ذلك على وجود بعض المحرمات في الأفعال في الصلاة لا تبطل بها الصلاة مثل مسابقة الإمام، أما تكبيرة الإحرام فلأنه نوى الاقتداء ولا يصح إلا أن يكون بعد تكبيرة الإحرام ولذلك نقل النووي وغيره الإجماع على بطلان الصلاة من كبر تكبيرة الإحرام قبل الإمام ناويًا الاقتداء به إلا أن يكون هناك سبب مثلها قلنا في الإمام إذا أتى الإمام الراتب وقد كان المستخلف قد صلى والمأمومون قد صلوا فينوون تغيير الاقتداء بالإمام الراتب إذا دخل في الصلاة بعدهم. هذه صورة أخرى غير التي نقل عليها الاتفاق، والصورة التي عليها الاتفاق أن يكونوا واقفين في الصف والإمام لم يقل بعد (الله أكبر) والمأموم يُكبر.`,
        f: [`(ص175) [ونحوهما] فيقتضي جميع الحركات، فالسنة في الحركات أن يبدأ المأموم في الحركة بعد أن يتمها الإمام وإذا ساواه فظاهر الأدلة التحريم وأغلظ منه المسابقة، وبعض العلماء يقولون تكره المساواة وتحرم المسابقة، ولكن الظاهر وقوع الفعل بعده ولكن قبل أن يتم الإمام حركته فهو مكروه بمعنى أن الإمام ينزل وهو ينزل بعده ولكن شاركه في جزء من الحركة فيكون مكروهًا، وذلك يُنبه على من يصلي خلف إمام يكبر قبل الحركة لأنه لا يبدأ حركته حتى يفعلها الإمام وليس فقط سماع الصوت، والأولى والسنة للإمام أن يكبر أثناء الحركة ويتم التكبير مع نهايتها أو قريبًا منه بحيث من لا يراه من المأمومين ويسمع صوته يستطيع أن يتابعه على السنة من غير اختلال. إذا نوى المفارقة فسلم قبل الإمام لعذر صحة صلاته، وأما إن كان بلا عذر ففيها القولين ولكن ظاهر الأدلة مثل رفع الرأس قبل الإمام.`, `(ص176) قوله ﷺ: (رأيت الجنة والنار) فيه أنهما مخلوقتان: أي الآن، موجودتان الآن، قد خلقتا ووجدتا.`] },
    ],
  },
  {
    title: `باب النهي عن رفع البصر إلى السماء في الصلاة (ص177–178)`,
    items: [
      { q: `رفع البصر إلى السماء في الدعاء: في الصلاة وخارجها`, p: `177–178`,
        n: `قوله ﷺ: (لينتهين أقوام يرفعون أبصارهم إلى السماء في الصلاة) أو لا ترجع إليهم. وفي رواية: (أو لتخطفن أبصارهم) فيه النهي الأكيد والوعيد الشديد في ذلك وقد نُقل الإجماع في النهي عن ذلك. قال القاضي عياض: واختلفوا في كراهة رفع البصر إلى السماء في الدعاء في غير الصلاة فكرهه شريح وآخرون وجوزه الأكثرون وقالوا لأن السماء قبلة الدعاء كما أن الكعبة قبلة الصلاة ولا يُنكر رفع الأبصار إليها كما لا يُكره رفع اليد قال الله تعالى: [وفي السماء رزقكم وما توعدون].`,
        o: `شريح وآخرون: يكره رفع البصر إلى السماء في الدعاء خارج الصلاة. الأكثرون: يجوز.`,
        s: `وهذا لم يثبت عن النبي ﷺ من رفع البصر للدعاء خارج الصلاة ونقل الإجماع عن النهي عن ذلك وظاهر هذا تحريم رفع البصر إلى السماء لأنه لا عقوبة إلا على فعل محرم.`,
        f: [] },
    ],
  },
  {
    title: `باب الأمر بالسكون في الصلاة والنهي عن الإشارة باليد ورفعها عند السلام وإتمام الصفوف الأول والتراص فيها والأمر بالاجتماع (ص178–182)`,
    items: [
      { q: `السكون في الصلاة والنهي عن رفع الأيدي عند السلام: المراد بالرفع، وما يُستفاد منه عمومًا`, p: `179–180`,
        n: `قوله ﷺ: (مالي أراكم رافعي أيديكم كأنها أذناب خيل شمس) هو بإسكان الميم وضمها، وهي التي لا تستقر بل تضطرب وتتحرك بأذنابها وأرجلها، والمراد بالرفع المنهي عنه هنا رفعهم أيديهم عند السلام مشيرين إلى السلام من الجانبين كما صرح به في الرواية الثانية.`,
        o: NO_O,
        s: `وهذا يستفاد منه عمومًا أن السكون في الصلاة أعم من ذلك، فعلى المصلي ألا يحرك أعضاءه في الصلاة إلا لحاجة لا كما نري فيحرك يده يميناً ويساراً ويلتفت، فذا ينافي الخشوع (اسْكُنُوا فِي الصَّلاَةِ) وإن كان الموضع الذي حركوا فيه أثناء السلام كما يفعل كثير من الناس فتجد أيديهم تتحرك مع السلام جهة الإشارة بالرأس.`,
        f: [] },
      { q: `الحلق في المسجد (الجلوس حلقًا حلقًا)، ومعنى «ما لي أراكم عزين»`, p: `180`,
        n: `قوله ﷺ: (ما لي أراكم عزين) أي متفرقين جماعة جماعة وهو بتخفيف الزاي الواحدة عزة معناه النهي عن التفرق والأمر بالاجتماع.`,
        o: NO_O,
        s: `فلا يوجد حلق (شِلل) في المسجد – جماعات متفرقة – بل يجتمعون وهذا أنفع لهم في مجالس علمهم وفي طعامهم وشرابهم ولكن في الطعام والشراب يجوز أن يكونوا جماعات ومتفرقين لقوله تعالى: (لَيْسَ عَلَيْكُمْ جُنَاحٌ أَن تَأْكُلُوا جَمِيعًا أَوْ أَشْتَاتًا) ولكن هنا لعلها في الحديث على وجود بعض الكلام وفي الدرس.`,
        f: [] },
      { q: `إتمام الصفوف الأول والتراص فيها، وصفوف الصبيان والنساء`, p: `180`,
        n: `وفيه الأمر بإتمام الصفوف الأول، والتراص في الصفوف، ومعنى إتمام الصفوف الأول أن يتم الأول ولا يشرع في الثاني حتى يتم الأول ولا في الثالث حتى يتم الثاني ولا في الرابع حتى يتم الثالث وهكذا إلى آخرها.`,
        o: NO_O,
        s: `فلا يُبدأ صف إلا بعد إتمام الصف الذي يسبقه، ومن هنا يقف الصبيان المميزين في الصف الأخير يُتم بهم الصف، ولا يبدأ صف صبيان مستقلاً عن صفوف الرجال الأخيرة حتى يُتم صف الرجال أولًا، وأما النساء فيبدأ صف مستقل لحديث أنس: [فَقَامَ عَلَيْهِ رَسُولُ اللَّهِ ﷺ وَصَفَفْتُ أَنَا وَالْيَتِيمُ وَرَاءَهُ وَالْعَجُوزُ مِنْ وَرَائِنَا فَصَلَّى لَنَا رَسُولُ اللَّهِ ﷺ رَكْعَتَيْنِ ثُمَّ انْصَرَفَ.] مسلم. (والتراص بمعنى عدم وجود فُرج.)`,
        f: [] },
      { q: `صيغة السلام من الصلاة: زيادة «وبركاته» وتسليمة اليمين واليسار، وهل هي بدعة؟`, p: `181`,
        n: `وفيه أن السنة في السلام من الصلاة أن يقول: [السلام عليكم ورحمة الله] عن يمينه [السلام عليكم ورحمة الله] عن شماله، ولا يُسن زيادة [وبركاته] وإن كان قد جاء فيها حديث ضعيف وأشار إليها بعض العلماء ولكنها بدعة إذ لم يصح فيها حديث بل صح هذا الحديث وغيره في تركها.`,
        o: NO_O,
        s: `هذا الكلام غير صحيح، نعم قد وردت أحاديث ضعيفة في ذلك ولكن قد وردت طرق أخرى صحيحة وإن كان الأكثر والأعم الاقتصار على ذكر الرحمة ولكن قد ثبتت زيادة [وبركاته] في بعض الروايات، فتحمل على الزيادة في بعض الأحيان وثبتت في اليمين دون الشمال وثبتت عن اليمين والشمال، فالصحيح أن هذه الأفعال يخير بينها لعدم تعارض الأفعال، وإن كان الأغلب الأعم القول [السَّلاَمُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ، السَّلاَمُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ] ويفعل أحيانًا أن يقول [السَّلاَمُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ، السَّلاَمُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ] وأحيانًا أخرى أقل: [السَّلاَمُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ، السَّلاَمُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ] فقد صحح ابن حجر حديث (وبركاته) وصححه الشيخ الألباني أيضًا.`,
        f: [`(ص181) وصححه الألباني في [صحيح وضعيف أبي داود]: عن وائل بن حجر عن أبيه: «صَلَّيْتُ مَعَ النَّبِيِّ ﷺ فَكَانَ يُسَلِّمُ عَنْ يَمِينِهِ: السَّلامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ، وَعَنْ شِمَالِهِ: السَّلامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ» [قال الألباني: صحيح]. وحديث ابن مسعود: «كَانَ يُسَلِّمُ عَنْ يَمِينِهِ وَعَنْ شِمَالِهِ حَتَّى يُرَى بَيَاضُ خَدِّهِ: السَّلامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ» (وفي حاشية التحقيق: لم ترد «وبركاته» في نسخة دار الكتب المصرية الخطية، وأثبتها محققو الرسالة عن نسختين، وأن ابن حجر أثبتها وأن ابن حبان في صحيحه أخرجها من حديث ابن مسعود، ورواها ابن خزيمة (٧٢٨) من طريق عمر بن عبيد، وفيه زيادة «وبركاته».)`] },
      { q: `الواجب من السلام: «السلام عليكم» مرة واحدة، واستحباب التسليمتين`, p: `182`,
        n: `والواجب منه السلام عليكم مرة واحدة، ولو قال السلام عليك بغير ميم لم تصح صلاته. وفيه دليل على استحباب تسليمتين، وهذا مذهبنا ومذهب الجمهور. وقوله ﷺ: (ثم يسلم على أخيه من على يمينه وشماله) المراد بالأخ الجنس أي إخوانه الحاضرين عن اليمين والشمال. وفيه الأمر بالسكون في الصلاة والخشوع فيها والإقبال عليها وأن الملائكة يصلون وأن صفوفهم على هذه الصفة والله أعلم.`,
        o: NO_O,
        s: `لحديث: عائشة أن رسول الله ﷺ [كان يسلم تسليمة واحدة تلقاء وجهه]. قال الشيخ الألباني: صحيح. سنن ابن ماجة. فيُجزئ تسليمة واحدة. قلنا قبل ذلك أن الراجح أن السلام واجب وليس بركن. والله أعلم. ولا تبطل الصلاة بالسلام عليك فقط.`,
        f: [] },
    ],
  },
  {
    title: `باب تسوية الصفوف وإقامتها وفضل الأول فالأول منها والازدحام على الصف الأول والمسابقة إليها وتقديم أولي الفضل وتقريبهم من الإمام (ص182–)`,
    items: [
      { q: `سبب حرص الصحابة على الصف الأول (القرعة عليه)، وترتيب الصفوف عند ازدحام الصف الأول`, p: `184`,
        n: `(حديث: «لو يعلم الناس ما في النداء والصف الأول ثم لم يجدوا إلا أن يستهموا عليه لاستهموا...»؛ «لو تعلمون ما في الصف المقدم لكانت قرعة».) [استهم: اقترع عليه].`,
        o: NO_O,
        s: `فينبغي أن يُبدأ الصف فيكمل الأول فالأول، فلا يُبدأ صف مؤخر بعيدًا عن الإمام كما يفعل كثير من الناس فيضعون صف من الكراسي ويقفون بالخلف.`,
        f: [] },
      { q: `تقديم أولي الأحلام والنهى في الصفوف: وقوف الصبيان، وترتيب القرب من الإمام (يمين الإمام ويساره)`, p: `185–186`,
        n: `قوله ﷺ: (ليلني منكم أولو الأحلام والنهى ثم الذين يلونهم ثم الذين يلونهم) ليلني هو بكسر اللامين وتخفيف النون [من غير ياء] قبل النون، ويجوز إثبات الياء مع تشديد النون على التوكيد. وأولو الأحلام: هم العقلاء وقيل البالغون. والنهى بضم النون العقول فعلى قول من يقول أولو الأحلام العقلاء يكون اللفظان بمعنى، فلما اختلف اللفظ عطف أحدهما على الآخر تأكيدًا، وعلى الثاني معناه: البالغون العقلاء. ... قوله ﷺ: (ثم الذين يلونهم) معناه الذين يقربون منهم في هذا الوصف. وقوله (يمسح مناكبنا) أي يسوي مناكبنا في الصفوف ويعدلنا فيها. وفي هذا الحديث: تقديم الأفضل فالأفضل إلى الإمام لأنه أولى بالإكرام ولأنه ربما احتاج الإمام إلى استخلاف فيكون هو أولى ولأنه يتفطن لتنبيه الإمام على السهو لما لا يتفطن له غيره وليضبطوا صفة الصلاة ويحفظوها وينقلوها ويعلموها الناس وليقتدي بأفعالهم من وراءهم ولا يختص هذا التقديم بالصلاة بل السنة أن يقدم أهل الفضل في كل مجمع إلى الإمام وكبير المجلس كمجالس العلم والقضاء والذكر والمشاورة ومواقف القتال وإمامة الصلاة والتدريس والإفتاء وإسماع الحديث ونحوها ويكون الناس فيها على مراتبهم في العلم والدين والعقل والشرف والسن والكفاءة في ذلك الباب، والأحاديث الصحيحة متعاضدة على ذلك. وفيه تسوية الصفوف واعتناء الإمام بها والحث عليها.`,
        o: `أولو الأحلام: العقلاء، وقيل: البالغون.`,
        s: `فيستفاد من هذا التفسير أن الصبيان لا يكونون خلف الإمام مباشرةً في الأصل وأما لو لم يوجد وراءه إلا الصبيان جاز فقد وقف أنس واليتيم خلف رسول الله ﷺ، ولذا فالصبي المميز يُعتد بوقوفه في الصف بحيث يُجعل صفاً مع الرجال، فلو رجل واحد وصبي واحد فيُجعلون صفاً مستقلاً فلا يكون الرجل بجوار الإمام كحالة عدم وجود الصبي بل يقف الصبي كالرجل فيعتد بوقوفه في الصف، لكن المشروع أن يكون القريب من الإمام هم أهل العلم وحفظ القرآن. وهذا يُستدل به على أن الصف يبدأ من الوسط، لأنه كلما كان أقرب من الإمام كلها كان أفضل فالذي يكون على يمين الإمام أفضل ثم الذي يكون على شماله لأنه أقرب إلى الإمام، ثم يبدأ بعد ذلك على اليمين ثم على الشمال ثم اليمين لأنه كل ما كان على اليمين وأقرب يكون أولى، ولذلك الواحد يبدأ عن يمين الإمام والثاني يأتي عن شمال الأول ويقفوا خلفه والثالث يأتي عن يمين الأول حتى يكون أقرب للإمام والرابع يقف عن شمال الثاني ليكون أقرب للإمام، فإم المأمون إذا وقف عن اليمين أولًا فسوف يبتعد عن الإمام كما يفعل الناس، وهكذا في الصف الثاني يبدأ من المنتصف ليكون أقرب للإمام وهذه أفضل المواطن لهذا الحديث. [ثُمَّ جِئْتُ حَتَّى قُمْتُ عَنْ يَسَارِ رَسُولِ اللَّهِ ﷺ فَأَخَذَ بِيَدِي فَأَدَارَنِي حَتَّى أَقَامَنِي عَنْ يَمِينِهِ ثُمَّ جَاءَ جَبَّارُ بْنُ صَخْرٍ فَتَوَضَّأَ ثُمَّ جَاءَ فَقَامَ عَنْ يَسَارِ رَسُولِ اللَّهِ ﷺ فَأَخَذَ رَسُولُ اللَّهِ ﷺ بِيَدَيْنَا جَمِيعًا فَدَفَعَنَا حَتَّى أَقَامَنَا خَلْفَهُ] مسلم. وهذا دليل على أن من يأتي ثانيًا يقف على يسار الأول وليس على يمينه ولو أخطأ في الوقوف حوله ﷺ كما حول ابن عباس ﵁. (في هذا الوصف): أي القرآن والسنة.`,
        f: [`(ص185) «لِيَلِنِي»: بمعنى: ليقرب مني. «النُّهى» جمع نُهية وهو العقل؛ وليس بينها تعارض.`] },
      { q: `معنى «إياكم وهيشات الأسواق» ورفع الصوت في المسجد`, p: `187`,
        n: `قوله ﷺ: (وإياكم وهيشات الأسواق) هي بفتح الهاء وإسكان الياء وبالشين المعجمة أي اختلاطها والمنازعة والخصومات وارتفاع الأصوات واللغط والفتن التي فيها.`,
        o: NO_O,
        s: `فعندما نجد أُناس ارتفعت أصواتها في المسجد نقول لهم قال ﷺ: (وَإِيَّاكُمْ وَهَيْشَاتِ الأَسْوَاقِ) فرفع الصوت في المسجد وخصوصاً الصياح في الأفراح يُنهى عنه لهذا الحديث.`,
        f: [`(ص187) وهذه من معجزات النبي ﷺ. (تعليقًا على «فإني أراكم خلف ظهري».)`, `(ص187) «أقيموا الصف»: وذلك يقع بالتساوي المنكب في المنكب والقدم في القدم ويقع بسد الخلل (الفرج).`] },
      { q: `معنى «لتسوّن صفوفكم أو ليخالفنّ الله بين وجوهكم»، وحكم تسوية الصفوف (واجبة أم سنة؟)`, p: `187–188`,
        n: `قوله ﷺ: (لتسوّن صفوفكم أو ليخالفنّ الله بين وجوهكم) – قيل معناه يمسخها ويحوّلها عن صورها لقوله ﷺ يجعل الله تعالى صورته صورة حمار. – وقيل يغيّر صفاتها. – والأظهر والله أعلم أن معناه يوقع بينكم العداوة والبغضاء واختلاف القلوب كما يقال: [تغيّر وجه فلان عليّ] أي ظهر لي من وجهه كراهةٌ لي وتغيّر قلبه عليّ، لأن مخالفتهم في الصفوف مخالفةٌ في ظواهرهم واختلاف الظواهر سبب لاختلاف البواطن. قوله (يسوّي صفوفنا حتى كأنما يسوّي بها القداح) القداح بكسر القاف، هي خشب السهام حين تنحت وتبرى... معناه يبالغ في تسويتها حتى تصير كأنها يقوم بها السهام لشدة استوائها واعتدالها. قوله (فقام حتى كاد يكبّر فرأى رجلًا بادياً صدره من الصف فقال: لتسوُّنّ عباد الله صفوفكم) فيه الحث على تسويتها. وفيه جواز الكلام بين الإقامة والدخول في الصلاة، وهذا مذهبنا ومذهب جماهير العلماء ومنعه بعض العلماء، والصواب الجواز وسواء كان الكلام لمصلحة الصلاة أو لغيرها أو لا لمصلحة.`,
        o: `بعض العلماء: يمنع الكلام بين الإقامة والدخول في الصلاة. (وقالوا: لا يجوز بعد أن أقاموا إلا أن يكبر الإمام.) في معنى المخالفة: المسخ، أو تغيير الصفات، أو إيقاع العداوة والبغضاء (الأظهر).`,
        s: `(أو الوجوه بمعنى الوجهة وهي نفس المعنى فالإرادات تختلف فتقع العداوة والبغضاء.) (أي: عدم الاحتياج إلى إعادة الإقامة.) قالوا لا يجوز بعد أن أقاموا إلا أن يُكبر الإمام، ولكن الصحيح أنه يجوز أن يأمرهم بالتسوية وغيرها. (أي لو أحد تكلم بكلمة فلا يُحتاج إلى تكرير الإقامة.) فالظاهر وجوب تسوية الصفوف لأنه لا عقوبة إلا لترك واجب، وليست شرطاً في صحة الصلاة إلا لو فقد وصف الصف فكانوا فُرادى ولكن إذا اختلفوا اختلافاً يسيراً مع بقاء وصف الصف فهذا خلاف الواجب ولكن ليس بمبطل للصلاة.`,
        f: [] },
      { q: `الأذان والصف الأول والتهجير: فضائلها والقرعة عليها (الاستهام)، ومعنى «التهجير»`, p: `189`,
        n: `قوله ﷺ: (لو يعلم الناس ما في النداء والصف الأول ثم لم يجدوا إلا أن يستهموا عليه لاستهموا) النداء هو الأذان والاستهام الاقتراع، ومعناه أنهم لو علموا فضيلة الأذان وقدرها وعظيم جزائه ثم لم يجدوا طريقًا يُحصّلونه به لضيق الوقت عن أذان بعد أذان أو لكونه لا يؤذن للمسجد إلا واحد لاقترعوا في تحصيله، ولو يعلمون ما في الصف الأول من الفضيلة نحو ما سبق وجاءوا إليه دفعة واحدة وضاق عنهم ثم لم يسمح بعضهم لبعض به لاقترعوا عليه. وفيه إثبات القرعة في الحقوق التي يُزدحم عليها ويُتنازع فيها. قوله (ولو يعلمون ما في التهجير لاستبقوا إليه) التهجير التبكير إلى الصلاة أي صلاة كانت. قال الهروي وغيره: وخصه الخليل بالجمعة والصواب المشهور الأول.`,
        o: `الخليل: التهجير خاص بالجمعة. المشهور: التبكير إلى أي صلاة.`,
        s: `أي لتمنوا أن كل واحد يؤذن وراء الآخر، ولكن الصحيح أن يؤذن للمسجد مؤذن واحد إلا أن يُحتاج إلى ذلك لاتساع المكان، فالأصل أن يؤذن للصلاة مرة واحدة من مؤذن واحد. المشروع عند اجتماعهم تقريب ألوا الأحلام حفاظ القرآن والسنة ونحو ذلك، فإن لم يكن فمن سبق إلى المكان، والمؤذن الراتب يُقدم وحسن الصوت يُجعل مؤذناً راتباً ولو وجد مؤذنين راتبين فأيهما أحسن وأندى صوتاً قُدم. وأنها سبيل للفصل في كثير من الخصومات في المواضع التي شُرع فيها الاقتراع وليس ذلك من القهار المحرم. فأصل الهاجرة قبل الظُهر – شدة الحر – ولكن استعمل [كأصبحت كذا] أي صِرت كذا، فليس شرطاً أن يكون وقت الصباح فقط، فيقاس عليها سائر الصلوات حتى ولو قلنا أن هذا هو أصل المعنى، والأقرب أن لفظ التهجير قد غُير في الاستعمال اللغوي إلى معنى التبكير مطلقاً؛ والتبكير أن يأتي قبل الأذان، هذا هو الأولى والأفضل فيدرك الفضيلة بين الأذان والإقامة كاملة ما لم يكن له عذر.`,
        f: [] },
      { q: `إطلاق «العتمة» على العشاء: هل هو مكروه؟ والجمع بين النهي ولفظ الحديث`, p: `190`,
        n: `قوله ﷺ: (ولو يعلمون ما في العتمة والصبح لأتوهما ولو حبوًا) فيه الحث العظيم على حضور جماعة هاتين الصلاتين والفضل الكثير في ذلك لما فيها من المشقة على النفس من تنغيص أول نومها وآخره ولهذا كانتا أثقل الصلاة على المنافقين. وفي هذا الحديث تسمية العشاء عتمة وقد ثبت النهي عنه وجوابه من وجهين: أحدهما أن هذه التسمية بيان للجواز وأن ذلك النهي ليس للتحريم. والثاني وهو الأظهر أن استعمال العتمة هنا لمصلحة ونفي مفسدة لأن العرب كانت تستعمل لفظة العشاء في المغرب فلو قال (لو يعلمون ما في العشاء والصبح) لحملوها على المغرب ففسد المعنى وفات المطلوب فاستعمل العتمة التي يعرفونها ولا يشكون فيها وقواعد الشرع متظاهرة على احتيال أخف المفسدتين لدفع أعظمهما.`,
        o: `قيل: النهي عن تسمية العشاء عتمة للتنزيه، والتسمية بيان للجواز؛ أو الأظهر: استعملها لمصلحة نفي المفسدة (اللبس مع المغرب).`,
        s: `ولكن على أي الأحوال فإنه لا يحرم لفظ (العتمة) فليس هناك تعارض ما بين الوجهين، فإن الوجه الأول لبيان الجواز، والثاني لبيان الحكمة والسبب في لماذا فعل النبي ﷺ ذلك.`,
        f: [`(ص190) قال البخاري: [باب من كره أن يقال للمغرب العشاء]... عبد الله المزني أن النبي ﷺ قال: «لاَ تَغْلِبَنَّكُمُ الأَعْرَابُ عَلَى اسْمِ صَلاَتِكُمُ الْمَغْرِبِ» قال الأعراب وتقول هي: العشاء. وفي صحيح مسلم عن عبد الله بن عمر: «لاَ تَغْلِبَنَّكُمُ الأَعْرَابُ عَلَى اسْمِ صَلاَتِكُمْ أَلاَ إِنَّهَا الْعِشَاءُ وَهُمْ يُعْتِمُونَ بِالإِبِلِ».`, `(ص190) «ولو حبوًا»: أي على الرُكب. والله أعلى وأعلم.`] },
      { q: `تعريف «الصف الأول»: هل هو المتصل من طرف المسجد إلى طرفه؟ أم من سبق إلى المسجد وإن صلى في صف متأخر؟ (وإذا انقطع الصف بعذر)`, p: `192`,
        n: `وقال طائفة من العلماء: الصف الأول هو المتصل من طرف المسجد إلى طرفه لا يتخللّه مقصورة ونحوها فإن تخلّل الذي يلي الإمام شيء فليس بأول بل الأول ما لا يتخلله شيء وإن تأخر. وقيل الصف الأول عبارة عن مجيء الإنسان إلى المسجد أولًا وإن صلى في صف متأخر. وهذان القولان غلط صريح وإنما أذكره ومثله لأنبه على بطلانه لئلا يغتر به والله أعلم.`,
        o: `طائفة من العلماء: الصف الأول هو المتصل من طرف المسجد إلى طرفه (وما تخلله شيء فليس بأول). وقيل: عبارة عن مجيء الإنسان إلى المسجد أولًا وإن صلى في صف متأخر. (النووي يعدّ القولين غلطًا صريحًا.)`,
        s: `وهذا هو الصحيح، أن الصف الأول لو فيه عذر اقتضى قطعه بمنبر أو عمود أو أي شيء آخر يكون هو الصف الأول أيضاً طالما قطع بعذر.`,
        f: [] },
    ],
  },
  {
    title: `باب أمر النساء المصليات وراء الرجال أن لا يرفعن رؤوسهن من السجود حتى يرفع الرجال (ص192–193)`,
    items: [
      { q: `ستر العورة والتحرز من انكشافها في الصلاة، وسقوط شيء من العورة بغير قصد (كشف الفخذ)، وصلاة النساء مع الرجال`, p: `193`,
        n: `قوله (رأيت الرجال عاقدي أزرهم) معناه عقدوها لضيقها لئلا يُكشف شيءٌ من العورة. ففيه الاحتياط في ستر العورة والتوقّي بحفظ السُّترة. وقوله (يا معشر النساء لا ترفعن رؤوسكن حتى يرفع الرجال) معناه لئلا يقع بصر امرأةٍ على عورة رجل انكشف وشبه ذلك. والله تعالى أعلم بالصواب وإليه المرجع والمآب.`,
        o: NO_O,
        s: `فالأصل أن الإزار يوضع في وسط الإنسان، فمن قلة ما عندهم من الثياب وليس عندهم ثياب فاضطروا أن يستروا نصفهم الأعلى والأسفل بالإزار فعقدوها على العُنق ليستروا المناكب بالإضافة إلى ستر الأفخاذ، وهذا فيه ما كانوا عليه من الشدة وضيق الحال ﷺ. (بربط الطرفين حتى لا تسقط.) وهذا دليل على أنه لو انكشف شيء من العورة بغير قصد فتداركه سريعاً لم تبطل صلاته. وعموماً يجب على الرجل والمرأة أن يستروا العورة حتى ولو منفرداً وحتى لو وجدت ستارة وانكشف شيء من العورة (بالنسبة إلى الرجل ما بين السرة والركبة وبالنسبة للمرأة ما سوى الوجه والكفين) وجب عليها المبادرة إلى ستره، وقد يُستدل به على أن الفخذ عورة لأن الذي يظهر مع عقد الأزر على العُنق ظهور شيء من الفخذ والله أعلم، وهو دليل على مشروعية ستر الكتف وليس أنه من العورة ولكنه من كمال الهيئة – ستر المنكبين – للرجل من كمال الهيئة في الصلاة ولذلك عقدوا الأزر على الأعناق، وفيه صبر الصحابة على الفقر والحاجة، وفيه صلاة النساء مع الرجال بدون ساتر بينهما، فوجود الساتر ليس فريضة من الفرائض ولكن هو من باب البعد عن الفتن.`,
        f: [] },
    ],
  },
];
